import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAN: [CaseTemplate] = [priceTagSwitch, mopedFlee, loudParty, dirtBikeStreet, underpassPaint, falseAlarmCall, fakeBadgeTrick, concealedPistolPurse, chainedDog, hitAndRunBumper, badCheckFeed, facebookThreat, repeatedTexts, drunkPorch, mailTheft, gasCanSiphon, tireSlash, tailgateShove, falseNameDeputy, scrapGutters, campusLaptop, returnFraud, fakeLicense, paintCans, dumpsterFire, tipJar, shedBreakIn, scaleAndBags, airsoftCar]

    static let priceTagSwitch = SmallCases.make(
        key: "story.priceTagSwitch",
        category: .property,
        headlines: ["Shopper Swapped Price Stickers at Hardware Store", "Man Says Cashier Rang Up the Wrong Tag"],
        law: "misdLarceny",
        spec: "Stole $126 in tools from a hardware store by switching price labels, on {DATE}.",
        ages: 24...62,
        victim: false,
        summary: "A hardware store manager watched {D} peel a $14 sticker from a box of washers and stick it over the label on a $140 drill bit set on {DATE}. {D} paid $14 at the register and left. {DL} says the stickers had fallen off the shelf display and {D.he} grabbed what was on the floor.",
        state: [E(.video, 3, "Aisle Camera", "{D} peels a sticker from a small box and presses it over the label on the drill bit set."), E(.document, 2, "Register Tape", "The drill bit set rung up at $14 with the washer SKU.")],
        defense: [E(.statement, 1, "Loose Stickers", "{DL} says the shelf had loose stickers on the floor.")],
        role: "Hardware store manager",
        exam: [.direct("What did you see from where you were working in the store?", "\"I was stocking the aisle around midday and saw {D} take a small price sticker off a box of washers and press it carefully over the label on a drill bit set.\""), .direct("What happened after that?", "\"{D.He} carried the drill bit set to register two and paid. It rang up at $14, which is the washer price, when that drill bit set sells for $140.\""), .direct("How did you confirm what you saw?", "\"I pulled the aisle camera footage afterward. It shows the sticker being peeled, moved, and smoothed down, and then I called the sheriff's office.\""), .direct("Where were you standing, and how far was that from the aisle?", "\"I was stocking washers one aisle over, maybe fifteen feet away. I could see between the shelves clearly, and the lighting in that part of the store is bright.\""), .direct("What is the price difference between the two items?", "\"The drill bit set is $140 on our shelf tag, and the box of washers is $14. That is a difference of $126 on a single sale.\""), .direct("What does the register show was sold?", "\"The register tape shows the drill bit set rung up at $14 using the washer SKU, so the scanner read the sticker on top and not the label underneath it.\""), .cross("Stickers fall off shelves in your store all the time, don't they?", "\"They do come loose sometimes, but they don't peel off one box and land squarely over the label on a more expensive one.\""), .cross("You watched this happen and never stopped {D.him} at the register, did you?", "\"No, I didn't. I wanted the video reviewed first and I didn't want a confrontation on the floor, so I let the sale finish.\""), .cross("Can you say what {D} was thinking when the sticker was moved?", "\"No, I can only tell you what the camera shows. I can't see inside anybody's head, only what the hands did.\""), .cross("How many stickers had come loose on that shelf in the past week?", "\"A few, maybe four or five. Our stickers do come off in that aisle sometimes, which is why I pulled the camera footage instead of assuming anything.\""), .cross("The cashier rang up what the box showed, correct?", "\"The cashier scanned whatever label was on top, so the sticker did the work. A cashier ringing that box would have had no reason to question it.\"")],
        theory: ("{D} moved a price sticker to pay one tenth of the price.", "Loose stickers and a cashier who rang up what the box said."),
        allocution: "\"I shouldn't have done it. I'll pay the difference.\"",
        truths: ("{DL}'s phone held a note, 'swap tags at the hardware store, they never check.'", "The store's own shelf stickers had been peeling for weeks, a stock clerk later said."),
        defendant: [.direct("Tell us what you were doing in the hardware store that day.", "\"I stopped in on my lunch break to pick up a drill bit set for a project at home. I grabbed one off the shelf and went straight to the register.\""), .direct("Did you move any price sticker from one item to another?", "\"Not on purpose. The stickers on that shelf were loose and there were a few on the floor, and I picked up what I thought belonged with the box.\""), .direct("What did you think when the cashier rang up $14?", "\"I thought it might be a sale. I trust the register, so I didn't study the number. I paid and walked out without thinking about it again.\""), .direct("How many items did you pick up in the store that day?", "\"Just two things, the washers I came for and the drill bit set. I had been meaning to buy a set of bits for a project at home.\""), .direct("Did you check the price of the drill bit set before you went to the register?", "\"Not carefully. I saw a price sticker on the box and figured that was the price. I was in a hurry and never read the shelf tag.\""), .direct("What did you do after the cashier rang you up?", "\"I paid, took the bag, and walked out. If I had thought anything was wrong I would have said something at the register.\""), .cross("The sticker sits exactly over the original label. How does that happen by accident?", "\"I can't explain the exact position. I know how it looks, but I didn't see it as a swap, and I wasn't trying to fool anybody.\""), .cross("You've bought tools before. Didn't a $140 drill bit set for $14 strike you as odd?", "\"I guess it should have. I was in a hurry and I assumed it was a clearance. I'm not saying I handled it well.\""), .cross("The camera shows you smoothing the sticker down with your thumb. Why do that?", "\"If a sticker was loose, I was pressing it flat so it wouldn't fall off again. That's a habit, not a plan.\""), .cross("The camera shows you in that aisle for almost a minute. What were you doing?", "\"Comparing sets and trying to decide which one to buy. A minute doesn't seem long to me for comparing tools I wasn't familiar with.\""), .cross("The one sticker that came off happened to be the $14 one, and it landed exactly on the label. Isn't that quite a coincidence?", "\"I can't explain how it ended up where it did. I know I paid what the register asked for, and I didn't think twice about the total.\"")],
        openings: ("A hardware store manager will tell you what the aisle camera caught: a $14 sticker peeled from a box of washers and pressed over the label on a $140 drill bit set. {D} then paid the lower price.", "This is a store with peeling stickers on its shelves and a shopper who trusted the register. The defense will show that {D} never looked closely at a price and never meant to cheat anyone."),
        closings: ("The camera does not blink. A sticker came off the washers, went over the drill bit label, and {D} paid ten cents on the dollar. Loose stickers do not place themselves that neatly.", "The State is asking you to read {DL}'s mind from a few seconds of video. The shelf stickers were loose, the register rang what it rang, and nobody proved {D} knew the price was wrong."),
        timeline: [(0, "Midday: the sticker is moved."), (0, "{DL} pays $14 at register two."), (0, "The manager reviews the aisle camera and calls deputies.")],
        identified: "The aisle camera.",
        mitigating: ["The defendant has accepted responsibility", "The defendant has a positive employment history and is gainfully employed"],
        genders: ["D": .male])

    static let mopedFlee = SmallCases.make(
        key: "story.mopedFlee",
        category: .traffic,
        headlines: ["Moped Rider Leads Deputy on Chase Through Backyards", "Man on Moped Ran From Blue Lights"],
        law: "fleeing",
        threshold: 6,
        spec: "Operated a motor vehicle on a street while fleeing from a law enforcement officer who was attempting to stop the vehicle, on {DATE}.",
        ages: 18...40,
        victim: false,
        summary: "A deputy turned on blue lights behind {D}'s moped for a missing tail light on {DATE}. {D} sped up to about 30 mph, cut through three backyards, and knocked over a clothesline before the moped ran out of gas. {DL} says {D.he} didn't see the lights and had earbuds in.",
        state: [E(.video, 3, "Dash Camera", "The moped accelerates away after the lights come on and leaves the road."), E(.document, 2, "Deputy's Report", "Siren and lights on for forty seconds; the moped never slowed.")],
        defense: [E(.statement, 1, "Earbuds", "{DL} says {D.he} was wearing earbuds and couldn't hear the siren.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you turn on your emergency lights behind the moped?", "\"The moped was being ridden with no working tail light on a residential street in the evening. I activated my blue lights to make a routine equipment stop.\""), .direct("What did the rider do when the lights came on?", "\"The rider sped up to around thirty miles an hour, glanced back at my car twice, and turned off the road through the first of three backyards.\""), .direct("How long were your lights and siren running?", "\"About forty seconds of lights and siren before the moped left the road, and the whole pursuit lasted roughly two minutes before the moped ran out of gas.\""), .direct("What did you see on the moped that made you act?", "\"The moped had no working tail light, and I was close enough behind it that I could tell. I turned on my emergency lights to make a traffic stop.\""), .direct("Describe the path the moped took after you activated your lights.", "\"It left the pavement near a driveway, cut through three backyards, and knocked down a clothesline. I followed on the road and lost sight of it a couple of times between houses.\""), .direct("How did the chase end?", "\"The moped ran out of gas behind the third yard. The rider stopped, I walked up, and the arrest was made without a struggle.\""), .cross("Isn't it true you can't say {D} heard your siren?", "\"I can't hear what the rider hears. What I can say is that the lights were lit up in the mirror and the rider looked back twice.\""), .cross("Did you see earbuds on the defendant when you made the arrest?", "\"I noticed earbuds around {D.his} neck afterward. I could not tell you whether they were in {D.his} ears while the moped was moving.\""), .cross("What damage was caused during the chase?", "\"A clothesline came down and a flower bed was torn up. Nobody was hurt, and no vehicles or people were struck.\""), .cross("How long were you behind the moped before you turned your lights on?", "\"Not long, maybe ten or fifteen seconds. I wanted to confirm the tail light was out before I made the stop.\""), .cross("Did you ever see the rider turn around and look at your patrol car?", "\"The dash camera shows the rider's head turn twice, but I can't tell from the video whether the rider was looking at my lights or at something else on the road.\"")],
        theory: ("{D} saw the deputy, looked back twice, and fled.", "A rider in earbuds who never heard the siren."),
        allocution: "\"I panicked when I saw the lights. I'm sorry for the yards.\"",
        truths: ("The helmet camera on {DL}'s moped showed {D.him} glancing back at the lights and laughing.", "The moped's helmet camera showed {D.him} wearing earbuds and nodding to music."),
        defendant: [.direct("What do you remember about the start of that ride?", "\"I was heading home in the evening on my moped with my earbuds in, listening to music. It was an ordinary ride until I realized something was behind me.\""), .direct("When did you first realize a patrol car was behind you?", "\"Honestly, not until I was already cutting through the yards. I saw a flash in my mirror and I panicked, and by then I did not know how to stop.\""), .direct("Why did you keep going once you knew?", "\"I was scared. I had a bad feeling about getting in trouble, and my head was just racing. Looking back, I should have pulled over right away.\""), .direct("Do you usually wear earbuds when you ride?", "\"Almost every time. It's a habit on a short ride home, and I keep the music loud enough that I can't hear much else, which I know now isn't smart.\""), .direct("What do you remember about going through the first yard?", "\"I saw lights in my mirror and by then I was already close to a driveway. I turned into the yard because it seemed like the quickest way off the road.\""), .direct("How did the ride end for you?", "\"The engine sputtered and died behind the third house. I got off, put my hands where the deputy could see them, and went along without an argument.\""), .cross("You looked back twice, didn't you? The dash camera shows it.", "\"I saw something over my shoulder. I did not know it was a deputy. It looked like headlights at first, and then I realized it was more.\""), .cross("A siren is loud. How did you miss it?", "\"With earbuds in and the music up, and the moped engine running, I honestly did not hear anything. I know that sounds convenient.\""), .cross("You drove through three yards. That is not the behavior of someone who is just confused, is it?", "\"It looks bad, I know. I was frightened and I made a bad choice. I was not trying to hurt anyone or damage property.\""), .cross("The engine is loud. Are you telling the jury you heard nothing else?", "\"I heard the engine because I was sitting on it, but the music was louder in my ears. The siren was behind me, and with the wind it just didn't register.\""), .cross("You turned into three yards. Isn't that exactly what someone does to lose a patrol car?", "\"I understand how it looks. At the time I thought I was avoiding something in the road, and I only understood what was behind me after the first yard.\"")],
        openings: ("It began with a missing tail light and ended with a moped tearing through three backyards. The State will show the deputy's lights, the sudden acceleration, and a rider who looked back twice before fleeing.", "A rider with earbuds in and music playing never heard a siren. The defense will show that {D} did not know a deputy was behind {D.him} until it was already too late to stop calmly."),
        closings: ("A deputy's lights and siren ran for forty seconds. The moped sped up, looked back twice, and cut across lawns. That is what a person does who knows the law is behind {D.him}, not someone who is simply lost in music.", "{D} had earbuds in, music playing, and an engine buzzing. Nothing proves {D.he} knew a deputy was behind {D.him}. Panic late in the ride is not the same as knowingly fleeing."),
        timeline: [(0, "Evening: blue lights behind the moped."), (0, "The chase through three backyards."), (0, "The moped runs out of gas and {DL} is arrested.")],
        identified: "The deputy's dash camera.",
        mood: .indifferent,
        genders: ["D": .male])

    static let loudParty = SmallCases.make(
        key: "story.loudParty",
        category: .publicOrder,
        headlines: ["Late-Night Party Ends With Disorderly Conduct Charge", "Host Says He Didn't Know Deputies Had Been Called Twice"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance, loud music and shouting after repeated warnings, on {DATE}.",
        ages: 21...45,
        victim: false,
        summary: "Deputies were called to {D}'s house at 11:10 p.m. and again at 1:20 a.m. on {DATE} for loud music. At the second visit {D} came onto the lawn yelling that the neighbors were \"snitches\" and refused to turn the speaker down. Two neighbors with infants signed complaints. {DL} says the party was a birthday and {D.he} was never told about the first visit.",
        state: [E(.video, 2, "Body Camera", "{D} on the lawn yelling at deputies while the speaker plays behind {D.him}."), E(.statement, 2, "Neighbor Complaints", "Two neighbors say the music went on until after 2 a.m.")],
        defense: [E(.statement, 1, "Birthday", "Guests say the party was a family birthday.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to the house for on the first visit?", "\"We received a complaint at 11:10 p.m. about loud music. When I arrived, I could hear the bass from the street, and a guest answered the door.\""), .direct("What happened when you returned at 1:20 a.m.?", "\"The music was louder than before. {D} came out onto the lawn yelling at us and calling the neighbors snitches, and refused to turn the speaker down.\""), .direct("Did you ask {D} to lower the volume?", "\"Yes. I asked twice, calmly, on the lawn. {D.He} kept shouting and said {D.he} would do what {D.he} wanted at {D.his} own house.\""), .direct("What did the neighbors tell you when you spoke with them?", "\"Two neighbors with infants said the music had kept the babies awake since late evening. Both signed complaints, and one said it was still going after two in the morning.\""), .direct("What did the defendant do when you reached the lawn the second time?", "\"{D.He} came out yelling that the neighbors were snitches and refused to turn the speaker down. About ten minutes after I arrived I placed {D.him} under arrest on the lawn.\""), .direct("What does your body camera show?", "\"It shows {DL} on the lawn yelling at us with the speaker playing behind {D.him}. The speaker is clearly audible over everything, including my requests.\""), .cross("On the first visit, you never actually spoke with the defendant, did you?", "\"That's correct. A guest answered the door and said {D.he} would pass the message along. I did not see {D.him} that first time.\""), .cross("The party was a birthday, wasn't it?", "\"That's what I was told, and it looked like one, with cake and balloons visible. A birthday does not change the noise rules after midnight.\""), .cross("Did anyone else on the lawn seem to be upset or yelling?", "\"No, the rest of the guests were fairly quiet by then. {D.He} was the one who was loud, and the music was still playing behind {D.him}.\""), .cross("How loud was the music on the first visit, since you never spoke to the defendant?", "\"It was loud enough from the street that a neighbor called. I didn't take a meter reading, so I can't give you a number.\""), .cross("Did you leave a card or a note at the door on the first visit?", "\"No. A guest answered the door, said the host was busy, and agreed to turn it down. I assumed the message would be passed along.\"")],
        theory: ("{D} was warned and kept the music loud while yelling at deputies.", "A birthday party and a host who never got the first warning."),
        allocution: "\"I got angry. I should have turned it off.\"",
        truths: ("A guest's video showed {DL} laughing and turning the volume up after the first visit.", "A guest confirmed no one told {DL} about the first visit."),
        defendant: [.direct("What was the occasion at your house that night?", "\"It was a family birthday party with friends and some relatives. We had food, a speaker out back, and people dancing, and it ran later than I planned.\""), .direct("Did anyone tell you deputies had come at 11:10?", "\"No. A guest answered the door and never told me. I only found out about the first visit when the deputies came back.\""), .direct("Why were you yelling on the lawn?", "\"I was embarrassed in front of my family and I was angry that someone called on a birthday. I said things I should not have said.\""), .direct("How many people were at the party, and who were they?", "\"About twenty, mostly family and a few friends from work. There were kids and older relatives, so we had people in the backyard and the front room.\""), .direct("Did you turn the volume up at any point after the first visit?", "\"I don't think I did, but a lot of people were handling the speaker that night, so I can't swear to what anyone touched.\""), .direct("What happened after deputies arrived the second time?", "\"I stepped outside and yelled when I should have talked, and a deputy placed me under arrest on the lawn. The music was still playing behind me.\""), .cross("You called your neighbors snitches in front of deputies, didn't you?", "\"I did, and I'm not proud of it. It came out in the heat of the moment.\""), .cross("You were asked twice to turn the speaker down. Did you?", "\"Not right away. I argued instead. I turned it off after I was told I was under arrest, which is not a good look.\""), .cross("The music was going past 1 a.m. Wasn't that too late for a house with babies next door?", "\"It was late, yes. I did not think about the infants next door, and I should have wrapped things up earlier.\""), .cross("You were asked twice to turn the music down. Why didn't you simply do it?", "\"I was angry and I wanted to make a point. If I had walked inside and turned it down right then, none of this would have happened.\""), .cross("Your neighbors have infants. Did you give any thought to them at that hour?", "\"Not enough. I was caught up in the party, and I should have thought about the babies next door when it got late.\"")],
        openings: ("Deputies were called to the same house twice in one night. By the second visit, the music was loud, the neighbors with infants were awake, and {D} was yelling on the lawn instead of turning the speaker down.", "This was a birthday party, and the person hosting it never got word of the first visit. The defense will show a host who was embarrassed and angry, not someone who defied a warning."),
        closings: ("Two calls, two visits, and a speaker that was still going after 1 a.m. Neighbors with infants signed complaints. A person who stands on the lawn yelling at deputies is not a person who was merely unaware.", "A guest answered the door the first time and {D} was never told. A loud birthday and some angry words on a lawn are not the same as defying a warning that never reached {D.him}."),
        timeline: [(0, "11:10 p.m.: first complaint."), (1, "1:20 a.m.: second visit."), (1, "1:30 a.m.: {DL} is arrested on the lawn.")],
        identified: "Neighbors' calls and deputies' reports.",
        genders: ["D": .male])

    static let dirtBikeStreet = SmallCases.make(
        key: "story.dirtBikeStreet",
        category: .traffic,
        headlines: ["Teen Popped Wheelies on County Road Near School", "Reckless Driving Charge After Dirt Bike Stunts"],
        law: "recklessDriving",
        spec: "Drove a motor vehicle on a highway carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...30,
        victim: false,
        summary: "A deputy saw {D} popping wheelies on a dirt bike at about 45 mph down a county road beside an elementary school at dismissal on {DATE}, weaving between cars. {D} has no license. {DL} says {D.he} was on a road with no traffic and didn't see any children.",
        state: [E(.video, 3, "Deputy's Dash Camera", "{D} on the rear wheel at speed, weaving past two cars and a crossing guard."), E(.document, 2, "School Schedule", "Dismissal began at 3:10 p.m., the time of the stop.")],
        defense: [E(.statement, 1, "No Traffic", "{DL} says the road was empty.")],
        role: "Sheriff's deputy",
        exam: [.direct("What first caught your attention on the county road that afternoon?", "\"I was driving toward the elementary school as dismissal started when a dirt bike came at me up on its rear wheel. My radar had it right around 45 miles an hour.\""), .direct("What time was that, and why does it matter?", "\"About 3:14 p.m. The bell had rung at 3:10, so buses were pulling in, parents were walking up, and the crossing guard had already stepped into the road.\""), .direct("How was the rider handling the traffic around the bike?", "\"The rider wove between two cars and then went past the crossing guard still on one wheel. I had to brake hard myself to stay clear of the whole thing.\""), .direct("Did you record any of that?", "\"Yes, my dash camera was running. It shows the first wheelie, the two cars, the guard with the stop sign, and then my lights coming on.\""), .direct("What happened once you got the rider stopped?", "\"I pulled the bike over around 3:16, a couple of minutes after I first saw it. The rider handed over no license because there wasn't one, and I identified {D} at the roadside.\""), .direct("What did you do about the bike and the rider?", "\"I cited {D.him} for reckless driving and driving without a license, and arranged for a parent to pick up the bike. {D.He} was polite once stopped and said nothing about any emergency.\""), .cross("Isn't it true no child was struck or even touched?", "\"That's correct, nobody was hit. But the bell had rung at 3:10 and the crossing guard was standing in the road with a stop sign when that bike came through.\""), .cross("How far was the bike from the nearest child you could see?", "\"I can't give you an exact distance. The video shows the guard and the cars clearly, but I didn't measure how far the nearest student was from the bike.\""), .cross("Your camera shows the road ahead of your cruiser, doesn't it, not the sidewalks?", "\"Mostly the road, yes. It shows the sidewalk edge at an angle, so I can't point to a specific child on the video who was in the bike's path.\""), .cross("You said the rider was doing about 45. Did you pace the bike?", "\"I paced it for only a few seconds before it slowed. I estimated 45 from my speedometer while closing, and I'd put it within five miles an hour either way.\""), .cross("Was the road itself empty of traffic, as {DL} says?", "\"No. There were two cars on it at the time and the bike passed between them. It was not an empty road, and it runs directly beside the school.\"")],
        theory: ("{D} did stunts at speed past a school at dismissal.", "A skilled rider on an empty road."),
        allocution: "\"I wasn't thinking about the kids. I won't do it again.\"",
        truths: ("A parent's phone video showed {DL} grinning at the crossing guard before the wheelie.", "The crossing guard said the bike was never within fifty feet of a child."),
        defendant: [.direct("What were you doing on that dirt bike?", "\"I was practicing wheelies. I'd been riding that bike for a couple of years and wanted to hold one longer than I managed the week before.\""), .direct("Why did you pick that stretch of county road?", "\"It's straight and it's usually quiet. I didn't really think about the school until I was already past the first part of it, and by then I was committed.\""), .direct("Did you see any children while you were riding?", "\"Not that I noticed. I was looking at the front wheel and the pavement ahead, not at the sidewalks or the school grounds.\""), .direct("How fast would you say you were going?", "\"I wasn't watching the speedometer. When the deputy told me 45, I didn't argue, because on that stretch with the wheel up that sounds about right.\""), .direct("Where did you learn to ride like that?", "\"Mostly on my cousin's farm, on dirt. I've done wheelies there on a field track for years, so I thought I had good control of the bike.\""), .direct("What did you do when you saw the deputy's lights?", "\"I set the front wheel down and pulled over right away. I didn't try to run, and I answered the questions I was asked.\""), .cross("You knew you didn't have a license, didn't you?", "\"Yes, I don't have one. I rode because it's a dirt bike and I figured that was for off-road, which I understand now was wrong.\""), .cross("You were on one wheel at about 45 miles an hour?", "\"About that, yes. I can't say I checked, but I won't argue with the number the deputy gave.\""), .cross("You passed two cars and the crossing guard, correct?", "\"There were cars and I went between them. I saw the crossing guard right at the end. I'm not saying it was safe, because it clearly wasn't a smart place to do it.\""), .cross("You knew there was a school on that road, didn't you?", "\"Yes, I've driven past it all my life. I just didn't connect it with three o'clock that day until I was already in the middle of the stunt.\""), .cross("Were you showing off for anyone?", "\"There were a couple of people in cars, and maybe I was proud of how long the wheelie lasted. I can't tell you I wasn't paying some attention to that.\"")],
        openings: ("At 3:10 the school bell rang, a crossing guard stepped into the road, and four minutes later a dirt bike came through on one wheel at 45 miles an hour. The deputy's dash camera recorded it, and the evidence will show who was riding and where.", "This was a young rider with a bike, a straight road, and a bad idea. Nobody was touched and no child was near the bike, and the State must prove willful disregard for others, not simply a stunt."),
        closings: ("Watch the dash camera again: two cars, a crossing guard, a school letting out, and a rider with no license balanced on one wheel. {D} did not have to hit anyone for this to be reckless, because the danger was the whole point.", "No one was struck, nothing was damaged, and the video does not show one child within reach of that bike. {D} made a poor choice on a quiet road, but a poor choice is not the willful disregard the statute requires."),
        timeline: [(0, "3:10 p.m.: dismissal begins."), (0, "3:14 p.m.: {DL} on the rear wheel past the crossing guard."), (0, "3:16 p.m.: deputy stops the bike.")],
        identified: "The deputy's dash camera.")

    static let underpassPaint = SmallCases.make(
        key: "story.underpassPaint",
        category: .property,
        headlines: ["Graffiti Covers Highway Underpass Wall", "Spray Paint Found in Teen's Car After Underpass Tagging"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly damaged real property of {V}, a concrete underpass wall, causing damage of $1,800, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "A 40-foot wall of a highway underpass was covered overnight on {DATE} with a spray-painted tag. The state transportation department put cleanup at $1,800. A deputy found {D} in a parked car near the underpass at 4 a.m. with eleven cans of paint and paint on {D.his} hands. {DL} says {D.he} was only bringing cans for a friend who painted a legal mural.",
        state: [E(.physical, 3, "Paint Cans", "Eleven cans, the same colors as the tag; paint on {D}'s fingers.", .search), E(.video, 2, "Highway Camera", "A figure with a backpack at the wall at 3:20 a.m.")],
        defense: [E(.statement, 1, "Mural", "{DL} says a legal mural project was planned for the next week.")],
        role: "Sheriff's deputy",
        exam: [.direct("Where and when did you encounter {D}?", "\"I was patrolling the highway corridor at about 4:05 in the morning and found {D} sitting in a parked car roughly a quarter mile from the underpass.\""), .direct("What did you find inside the car?", "\"Eleven cans of spray paint in the back seat, in the same colors as the tag on the wall, and several of them were open.\""), .direct("What did you notice about the defendant's hands?", "\"There was paint on the fingers, still tacky to the touch, and a smear on one sleeve. It was not dried or old paint.\""), .direct("What was the condition of the wall when you saw it?", "\"A forty-foot stretch of the underpass wall was covered with a large painted tag in black and red. Some of the paint was still glossy, which told me it had not been there long.\""), .direct("Where was the car in relation to the underpass?", "\"About a quarter mile away, parked on a service road with the engine off. It was the only vehicle on that stretch at four in the morning.\""), .direct("What did the defendant say when you asked what {D.he} was doing there?", "\"{DL} said {D.he} was waiting for a friend and that the paint was for a legal mural planned for the next week. {D.He} had no paperwork with {D.him} and said the friend had it.\""), .cross("Isn't it true that no one saw the defendant actually painting the wall?", "\"That's right. The highway camera shows a figure with a backpack at the wall at 3:20, but it is at a distance and I can't make out a face.\""), .cross("Did the defendant tell you the cans were for a legal mural?", "\"Yes, {DL} told me that right away and said a friend was planning a mural the next week. I did not verify that during the stop.\""), .cross("Are those paint colors unusual?", "\"No. They are common colors you can buy at any hardware store, so I would not rely on color alone.\""), .cross("Did anyone place {D} at the wall at 3:20 a.m.?", "\"Only the highway camera, and it shows a figure with a backpack. The footage doesn't show a face, so I can't tell you who it was from the video alone.\""), .cross("How long had the defendant been sitting in that car before you arrived?", "\"I can't say. I found the car at 4:05, and the tag was finished about 3:50, so it could have been a quarter of an hour or it could have been much less.\"")],
        theory: ("{D} tagged a public wall at night and had the paint on {D.his} hands.", "A courier of cans for a friend's legal project."),
        allocution: "\"I tagged it. I'll clean it up myself.\"",
        truths: ("A photo on {DL}'s phone showed the finished tag next to the date and a caption, 'my name.'", "The friend came forward and said {DL} only carried cans and never painted."),
        defendant: [.direct("Why were you parked near the underpass at 4 a.m.?", "\"I was waiting on a friend who was supposed to meet me with a ladder for a mural project the following week. The friend was late, so I sat in my car.\""), .direct("Where did the eleven cans come from?", "\"They were for the mural. I had been carrying them for my friend, who plans to paint it legally, with permission, the next week.\""), .direct("How did you get paint on your fingers?", "\"I tested one of the cans in the car to check the color and the nozzle. It sprayed on my hand. That's all it was.\""), .direct("Tell us about your friend and the mural.", "\"My friend told me a legal mural project had been planned for that wall the following week. The plan was for me to bring the cans over so we could be ready to start.\""), .direct("Did you go up to the wall that night?", "\"I drove near the underpass to see where we would be working. I didn't touch the wall and I didn't paint anything.\""), .direct("What did you tell the deputy at the car?", "\"I told the deputy exactly what I'm telling you, that I was waiting on a friend and carrying cans for a legal mural. I offered my friend's name right then.\""), .cross("Why test paint at 4 a.m. in the dark, a quarter mile from the wall?", "\"It's what I was doing while I waited. It was a bad hour for it, but I was bored and I was waiting on my friend.\""), .cross("The cans match the colors on the wall. That's a coincidence?", "\"They are common colors, and my friend picked them. I'm not saying it looks great for me, but I didn't paint that wall.\""), .cross("Can you give the jury the name of the friend or the permission paperwork?", "\"I can give my friend's name, but I never saw a permit. I trusted the plan was legitimate, and I admit I never asked for paperwork.\""), .cross("A figure with a backpack was at the wall at 3:20 a.m. Was that you?", "\"No. I own a backpack like most people do, but I was not at the wall at that hour.\""), .cross("Eleven cans in a car for a mural a week away. Why bring them that night?", "\"My friend wanted to start early and asked me to drop them off. I thought it was a favor and never thought about how it would look at four in the morning.\"")],
        openings: ("A forty-foot wall was covered in spray paint overnight. A deputy found {D} a quarter mile away at 4 a.m., with eleven cans in the car and paint still wet on {D.his} fingers.", "The State has a figure on a camera, paint cans, and paint on a hand. The defense will show a courier waiting for a friend with supplies for a mural that was planned to be legal."),
        closings: ("Eleven cans, the same colors as the tag, and paint that was still wet on {D}'s fingers at four in the morning. The camera shows a figure at the wall at 3:20. Put those together and you know who painted it.", "No one saw {D} paint anything. The camera shows only a distant figure, the colors are common, and a mural project was planned. The State has suspicion and wet fingers, not proof of who held the can."),
        timeline: [(0, "3:20 a.m.: a figure at the underpass wall on camera."), (0, "3:50 a.m.: the tag is finished."), (0, "4:05 a.m.: {DL} is found in a nearby car.")],
        identified: "A deputy's patrol and a highway camera.",
        genders: ["D": .male])

    static let falseAlarmCall = SmallCases.make(
        key: "story.falseAlarmCall",
        category: .publicOrder,
        headlines: ["Prank 911 Call Sent Fire Trucks to Ex's House", "Man Charged for False Fire Report"],
        law: "falseReport",
        spec: "Willfully made a false report to law enforcement that a house was on fire, on {DATE}.",
        ages: 19...50,
        victim: false,
        summary: "A man called 911 at 9:50 p.m. on {DATE} to report flames visible at a house on a quiet road. Two engines and a deputy arrived to find no fire, only the residents, {D}'s ex-wife and her new partner, eating dinner. The call came from a prepaid phone that was later traced to a store where {D} paid cash. {DL} says {D.he} was nowhere near and that anyone could have used {D.his} number.",
        state: [E(.digital, 3, "911 Recording", "A man says a house is on fire and hangs up."), E(.document, 2, "Prepaid Phone Record", "The phone was bought with cash at a store near {D}'s work two days earlier.")],
        defense: [E(.statement, 1, "Alibi", "{DL}'s coworker says they were at a bowling alley.")],
        role: "Sheriff's detective",
        exam: [.direct("How did this investigation begin for you?", "\"Dispatch sent two engines and a patrol deputy to a reported house fire at 9:50 p.m. When they arrived there was no fire at all, only the residents finishing dinner.\""), .direct("Who was inside the house?", "\"{D}'s ex-spouse and the ex-spouse's new partner. They were eating at the kitchen table and had no idea anyone had called until the engines pulled up.\""), .direct("What did the 911 recording contain?", "\"A short call, a caller saying the house on that road was on fire with flames visible, then the line going dead. The caller gave the correct address but no name.\""), .direct("What did you learn about the phone that placed the call?", "\"It was a prepaid phone. Records traced it to a store near {D.his} workplace, where it was purchased with cash two days before the call.\""), .direct("Why did you look at {D} in particular?", "\"The address belonged to {DL}'s ex-spouse, there was a history of dispute between them, and the store sale put {DL} near where the phone was bought.\""), .direct("How long were the engines tied up on that call?", "\"They left about 10:10 p.m. after clearing the house. Two engines were committed for roughly twenty minutes, which is a real cost when a genuine call could have come in.\""), .cross("Did anyone identify the defendant's voice on the recording?", "\"No. Nobody has made a voice identification, and I did not ask for a formal voice comparison. The caller was brief and the audio is not great.\""), .cross("Did you recover the prepaid phone from the defendant?", "\"No. We never recovered the phone itself. It was switched off after the call, and I only have the records of where it was bought and when.\""), .cross("Who else near the store could have bought that phone?", "\"Anyone. It's a busy store near several workplaces. I have the sales record, but I can't say the buyer's face on video was positively {DL}.\""), .cross("Did you check where the defendant was at 9:50 p.m.?", "\"I was told {DL} was at a bowling alley with a coworker. I have not tied {DL}'s own phone to any location that night, so I can't contradict that.\""), .cross("Isn't it true anyone could have used the defendant's number or name?", "\"The call itself didn't use {DL}'s number, so that's right. What links {DL} is the store purchase and the dispute, not the number dialed from.\"")],
        theory: ("{D} sent fire trucks to an ex's house from a burner phone.", "A bowler with a coworker's alibi and no voice match."),
        allocution: "\"I was angry at her. I'm sorry for the trouble.\"",
        truths: ("A cashier remembered {DL} buying the prepaid phone and saying, 'it's a gift for a friend.'", "The bowling alley's score sheet showed {DL} bowling during the call."),
        defendant: [.direct("Where were you at 9:50 p.m. that night?", "\"I was at the bowling alley with a coworker, in the middle of a league game. We'd been there since a little after eight and stayed until about eleven.\""), .direct("Who can confirm that?", "\"My coworker was bowling on the lane next to mine, and the alley keeps score sheets. I think the sheet shows frames across the time of that call.\""), .direct("Do you know the people who live at that house?", "\"Yes, it's my ex-spouse and a new partner. Things ended badly and we haven't spoken in months, but I wouldn't send fire trucks to anyone's door.\""), .direct("Did you buy a prepaid phone two days before?", "\"I buy things in cash a lot, and I do stop at that store near work. I don't remember buying a prepaid phone, though, and I don't have one.\""), .direct("How has this affected you?", "\"Honestly I was hurt about it, and I said some angry things to friends. Being angry and calling in a fire are very different things, and I didn't do the second one.\""), .direct("What would you say to the idea that it was meant to scare them?", "\"If someone wanted that, they got it. I'm sorry they were frightened, but it wasn't me, and I'd never have put firefighters in danger over a grudge.\""), .cross("You were angry at your ex-spouse, weren't you?", "\"I was upset about how things ended, yes. I never denied that. It was months old by then and I'd mostly moved on.\""), .cross("The phone was bought with cash at a store near your work?", "\"That's what they tell me. Plenty of people from that area shop there, and my paying cash for things doesn't mean I bought that phone.\""), .cross("Is the bowling alley close enough that you could have slipped out?", "\"It's about fifteen minutes from that house. I didn't leave the lanes, but I know I can't prove every minute with a stopwatch.\""), .cross("Did you call your coworker after you heard about the fire call?", "\"I texted a few friends when a mutual friend told me about it. I said it was a crazy thing to do and that I'd been bowling.\""), .cross("Do you know anyone who would want to make trouble for the household?", "\"I can think of people who weren't happy with how the breakup went, but I won't point at anyone without something solid. Whoever it was, the answer starts and ends with this: I was bowling.\"")],
        openings: ("At 9:50 on a quiet evening, a caller reported flames at a house on a country road, and two fire engines raced out to find a family eating dinner. The evidence will show the call came from a prepaid phone bought for cash near {D}'s workplace, at the house of an ex who had cause for conflict with {D}.", "The State has a dead phone, a cash sale at a busy store, and an old grudge. It has no voice match, no phone in {D}'s hand, and a score sheet that puts {D} in a bowling alley at the moment the call was made."),
        closings: ("Put it together: a cash purchase two days before, a false report at the home of {D}'s ex-spouse, and a motive that was never hidden. Firefighters were pulled from their station for a fire that never existed, and {D} is the person the trail leads to.", "Nobody identified a voice, nobody found the phone, and the score sheet places {D} bowling during the call. A grudge and a store receipt are not enough to say beyond a reasonable doubt that {D} made that call."),
        timeline: [(-2, "A prepaid phone is bought with cash."), (0, "9:50 p.m.: the false fire call."), (0, "10:10 p.m.: engines leave; deputies open a report.")],
        identified: "Phone records traced to a store.",
        mood: .indifferent,
        genders: ["D": .male])

    static let fakeBadgeTrick = SmallCases.make(
        key: "story.fakeBadgeTrick",
        category: .publicOrder,
        headlines: ["Man Flashed Toy Badge at Convenience Store", "Impersonation Charge Over a Free Sandwich"],
        law: "impersonatingLEO",
        spec: "Falsely pretended to be a law enforcement officer, displaying a badge, to obtain a benefit, on {DATE}.",
        ages: 22...60,
        victim: false,
        summary: "A clerk says {D} flashed a gold badge at a convenience store counter on {DATE}, said, \"Sheriff's office, I get the discount,\" and was handed a $7 sandwich for free. The badge turned out to be a costume piece from a novelty store. {DL} says it was a joke and the clerk laughed.",
        state: [E(.video, 3, "Store Camera", "{D} holds up a badge and receives a sandwich without paying."), E(.physical, 2, "The Badge", "A plastic gold badge stamped with the name of a novelty store.")],
        defense: [E(.statement, 1, "A Joke", "{DL} says the clerk laughed and played along.")],
        role: "Convenience store clerk",
        exam: [.direct("What do you do at the convenience store?", "\"I work the register on the day shift. Lunchtime is the busiest part of my day, with a line for sandwiches and fountain drinks from about eleven-thirty on.\""), .direct("What happened when {D} reached the counter?", "\"{D} held up a gold badge, said it was the sheriff's office and that {D.he} got the discount, and then I handed over a seven dollar sandwich without ringing it up.\""), .direct("What did the badge look like to you?", "\"Gold-colored, shield shaped, in a little leather holder. I looked at it for a second or two and didn't read the small print around the edge.\""), .direct("Did the defendant pay anything?", "\"Nothing. {D.He} took the sandwich and walked out. The register shows no sale for that item, and I had to explain the shortage at the end of my shift.\""), .direct("How did you find out the badge wasn't real?", "\"I showed the store camera footage to a deputy the next day. The deputy told me it was a costume piece with the name of a novelty store stamped on it.\""), .direct("What does the store policy say about law enforcement discounts?", "\"We don't have one written down. Some of the regulars in uniform get a drink or a sandwich at half price, which the owner allows, but nothing is free.\""), .cross("Isn't it true you laughed when the defendant showed you the badge?", "\"I may have smiled. It was lunchtime and the line was long, and I don't remember a big laugh. I'm not going to claim I took it in a serious spirit.\""), .cross("Did the defendant ever say the words, I am a deputy?", "\"The words were, sheriff's office, I get the discount. {D.He} never said a name or a badge number, and I didn't ask for either.\""), .cross("Did you check an ID or ask for anything else?", "\"No, I didn't. I handed the sandwich over quickly because customers were waiting, and I know now that I should have asked for more.\""), .cross("Did you tell a coworker how you felt about it?", "\"I told a coworker it was kind of funny at first. After I counted the drawer I was less amused, and that's when I took it to the deputy.\""), .cross("Did anyone in line react to the badge?", "\"One customer behind {DL} looked over, but nobody said anything that I heard. The camera shows the whole exchange lasting less than a minute.\"")],
        theory: ("{D} showed a badge and claimed to be a deputy to get a free meal.", "A joke with a plastic badge and a clerk who played along."),
        allocution: "\"It was a stupid joke. I'll pay for the sandwich.\"",
        truths: ("{DL} had used the badge three times at other stores that month.", "The clerk had told a coworker it was funny and he gave it away on purpose."),
        defendant: [.direct("Why did you take a badge into that store?", "\"It was a novelty piece I'd bought as a gag. A friend and I have been joking around with it, and I used it as a joke on the clerk that day.\""), .direct("What exactly did you say to the clerk?", "\"I said, sheriff's office, I get the discount, with a grin. I honestly meant it as a bit, and I expected the clerk to laugh and ring me up.\""), .direct("What was the clerk's reaction?", "\"The clerk smiled and shook their head a little, then handed the sandwich over. I read that as playing along. I didn't think I was fooling anybody.\""), .direct("Why didn't you pay afterward?", "\"I walked out before I thought it through. It was seven dollars, and in the moment it felt like part of the joke, which I know sounds weak.\""), .direct("Have you ever held a law enforcement job?", "\"Never. I have no connection to the sheriff's office, and I've never told anyone I was a deputy outside of a joke with friends.\""), .direct("What did you do when the deputy contacted you?", "\"I told the truth right away. I said it was a plastic badge from a novelty store, showed it, and said I'd pay for the sandwich.\""), .cross("You've used that badge at other stores, haven't you?", "\"A couple of times I flashed it for fun at places where people knew me, and nothing came of it. I didn't get anything free that I remember.\""), .cross("This was the first time you got food without paying?", "\"Yes, this was the only time it happened with food. I'm not proud of it and I'm not going to pretend it was an accident.\""), .cross("You chose to say you got a discount, a specific benefit, right?", "\"I said it because that was the joke. I know a joke that ends with a free sandwich looks different on camera than it felt at the counter.\""), .cross("You knew the clerk could not tell the badge was a toy?", "\"I figured the clerk could probably tell, since it's a cheap thing. But I can't see inside the clerk's head, and I realize it looked real enough on that video.\""), .cross("Did you offer to pay at the time or only later?", "\"Only later, after the deputy called. At the counter I walked out, so I understand why the store felt it was taken.\"")],
        openings: ("{D} walked up to a convenience store counter at lunchtime, flashed a gold badge, claimed to be with the sheriff's office, and left with a seven dollar sandwich without paying. The camera records the whole exchange, and the badge turned out to be a novelty costume piece.", "This was a gag with a plastic badge, told to a clerk who smiled and played along. The defense says nobody was deceived into losing anything, and a joke at a sandwich counter is not a crime."),
        closings: ("Watch the store camera: a badge raised, a claim of authority, and a sandwich handed over with no sale rung up. A plastic prop does not turn a false claim to be a deputy into a harmless prank when it puts food in {D}'s hands.", "The clerk laughed, the badge was obviously cheap, and {D} told the truth to the deputy the moment asked. The State has a prank that went too far in a lunch rush, not proof of an intent to defraud the store."),
        timeline: [(0, "Lunchtime: {DL} shows the badge."), (0, "The clerk hands over the sandwich."), (1, "The clerk shows the camera to a deputy.")],
        identified: "The clerk's report and the store camera.",
        genders: ["D": .male, "V": .male])

    static let concealedPistolPurse = SmallCases.make(
        key: "story.concealedPistolPurse",
        category: .publicOrder,
        headlines: ["Woman Carried Pistol in Purse at County Fair", "No Permit, Deputies Say, After Pistol Found in Handbag"],
        law: "concealedWeapon",
        spec: "Carried a concealed handgun, a .380 pistol, on and about {D.his} person without a permit, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "A deputy saw the grip of a pistol in the open top of {D}'s purse at the county fair on {DATE} when {D} set it on a table. {D} had no concealed carry permit. {DL} says the purse was a gift from {D.his} late husband, that the pistol was a keepsake {D.he} carried to the fair to show a friend, and that {D.he} didn't know it needed a permit.",
        state: [E(.physical, 3, "The Pistol", "A loaded .380 pistol with a chambered round in a zippered pocket.", .search), E(.document, 2, "Permit Check", "No concealed handgun permit on file.")],
        defense: [E(.statement, 1, "Keepsake", "{DL}'s friend says it belonged to {D.his} late husband.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did you come to notice the pistol?", "\"I was working the county fair that evening and walking past the food tables when {D} set a purse on a table. The top was open and I saw a pistol grip inside.\""), .direct("What did you do next?", "\"I approached and asked {D.him} if there was a firearm in the purse. {D.He} said yes, that it was a keepsake, and handed the purse over without any argument.\""), .direct("What kind of pistol was it?", "\"A .380 caliber pistol. It was in a zippered pocket inside the purse and had a round chambered, so it was loaded and ready to fire.\""), .direct("How crowded was the fair at that time?", "\"Very. It was early evening, the busiest stretch of the night, with families on the midway and a long line at the funnel cake stand within thirty feet.\""), .direct("What did your permit check show?", "\"No concealed handgun permit on file for {D.him}. I ran it from my cruiser radio and the answer came back within a few minutes.\""), .direct("How did {D} behave during the encounter?", "\"Calmly and politely. {D.He} was upset and embarrassed, explained it belonged to a late spouse, and cooperated when I took the pistol and made it safe.\""), .cross("Isn't it true you only saw the grip because the purse was open?", "\"Yes. The purse top was open on the table and the grip was visible. I didn't search anything until I had that sight.\""), .cross("Did the defendant point the pistol or touch it in the crowd?", "\"No. {D.He} never touched it while I watched. It stayed in the pocket the whole time until I removed it.\""), .cross("Did the defendant try to hide the purse or walk away?", "\"Not at all. {D.He} had just set it down on the table and stood next to it. I didn't see any attempt to conceal it from me.\""), .cross("Did the defendant threaten or say anything alarming?", "\"Nothing like that. {D.He} was nervous about the questions, but there was no threat, no argument, and no one around had complained about {D.him}.\""), .cross("How do you know how long the pistol had been in that purse?", "\"I don't. I only know what I saw that evening. Whether it had been there a day or a year isn't something I can tell from the gun.\"")],
        theory: ("{D} carried a loaded pistol in a purse without a permit at a crowded fair.", "A widow who carried a keepsake and didn't know."),
        allocution: "\"I didn't know. I'll turn it in.\"",
        truths: ("{DL} had practiced at a range the weekend before and knew the permit rules.", "The pistol had been in the purse since the funeral, a friend said."),
        defendant: [.direct("Whose pistol was it?", "\"It belonged to my late spouse. It had been in a drawer for years, and I put it in my purse after the funeral and never took it out.\""), .direct("Why did you have it at the fair?", "\"A friend I was meeting had asked about it, and I wanted to show it as a keepsake. I wasn't there to use it on anyone.\""), .direct("Did you know you needed a permit to carry it in a purse?", "\"I didn't think of it that way. To me it was an object I was bringing to show someone, not a gun I was carrying for protection.\""), .direct("What did you do when the deputy asked about it?", "\"I told the truth immediately. I said yes, there's a pistol, here it is, and I handed the purse over and apologized.\""), .direct("How had you used or handled that pistol before?", "\"Barely. My spouse kept it for protection, and I never liked touching it. I've held it only when cleaning out things at home.\""), .direct("How are you feeling about all this?", "\"Embarrassed and sorry. I wouldn't hurt anybody, and I didn't mean to put a loaded gun anywhere near people at a fair.\""), .cross("The pistol was loaded, wasn't it?", "\"The deputy says it had a round chambered. I honestly don't remember checking. I'm not familiar enough to say, and I'll accept what the deputy found.\""), .cross("You carried it in a crowded place?", "\"Yes, the fair was crowded. I didn't think about the crowd until the deputy talked to me, and I can see now how that looks.\""), .cross("Did you go to a shooting range the weekend before?", "\"I went with a friend, yes, and I fired a few rounds. That was a casual outing and I don't claim to know every rule about permits.\""), .cross("So you had some familiarity with firearm rules?", "\"A little. I knew handguns needed some paperwork to buy. I didn't know the permit rules applied to a keepsake in a bag, and I should have asked.\""), .cross("You had no permit, correct?", "\"Correct, I have never had a concealed handgun permit. I never thought I'd need one until that evening.\"")],
        openings: ("On a crowded evening at the county fair, a deputy saw the grip of a loaded .380 pistol in the open top of a purse. The State will show a chambered round, no concealed handgun permit, and a gun carried among families and children.", "This is a person who carried a late spouse's keepsake to show a friend and told the deputy the truth at once. The defense says there was no threat, no brandishing, and no criminal purpose behind what was in that purse."),
        closings: ("A loaded pistol with a chambered round sat in a purse at the busiest hour of the fair, and {D} had no permit. The law does not carve out an exception for a keepsake, no matter how sincerely it was kept.", "The pistol never left the zipper, nobody was threatened, and {D} handed it over the second a deputy asked. This is grief and a misunderstanding of the rules, not the criminal carrying the law was written to stop."),
        timeline: [(0, "Evening: {DL} sets the purse on a table."), (0, "A deputy sees the grip of a pistol."), (0, "{DL} is arrested at the fair.")],
        identified: "A deputy's sight of the grip.",
        genders: ["D": .female])

    static let chainedDog = SmallCases.make(
        key: "story.chainedDog",
        category: .publicOrder,
        headlines: ["Dog Left Chained Without Water in August Heat", "Animal Control Charges Owner After Dog Collapses"],
        law: "animalCruelty",
        spec: "Intentionally deprived an animal, a dog, of necessary sustenance, water, in the owner's care, on {DATE}.",
        ages: 22...60,
        victim: false,
        summary: "Animal control found {D}'s hound chained to a post in the yard on {DATE} in 97-degree heat with an empty water bowl and no shade. The dog was lethargic and panting. {D} was at work. {DL} says the dog had a full bowl that morning and a neighbor must have kicked it over.",
        state: [E(.physical, 3, "The Bowl", "An empty bowl and a chain that reached only to the post, with no shade.", .search), E(.document, 2, "Veterinary Report", "Heat exhaustion; the dog recovered after fluids and cooling.")],
        defense: [E(.statement, 1, "Full Bowl", "{DL} says the bowl was full at 7 a.m.")],
        role: "Animal control officer",
        exam: [.direct("What called you out to {D}'s address?", "\"A neighbor phoned animal control about 2 p.m. saying a hound had been chained in the sun all day. I arrived within the hour and found the dog in the yard.\""), .direct("What did you see when you got there?", "\"A hound chained to a post, panting hard, lying flat with its tongue out. The water bowl was empty and there was no shade anywhere within the reach of the chain.\""), .direct("What was the temperature?", "\"The weather service had it at 97 degrees that afternoon. The ground in the yard was baked hard, and the metal chain clip was too hot for me to hold comfortably.\""), .direct("How did the dog respond to you?", "\"It was lethargic. It lifted its head but didn't get up, and it didn't have the energy to bark. That told me it had been exposed for hours.\""), .direct("What did you do for the dog?", "\"I gave it water, wet it down, and took it to the veterinarian around 3 p.m. The report diagnosed heat exhaustion and noted the dog recovered after fluids and cooling.\""), .direct("Where was the defendant when you arrived?", "\"At work. I reached {D} by phone, and {DL} said the dog had a full bowl that morning and that someone must have disturbed it.\""), .cross("Isn't it true the dog survived and recovered completely?", "\"Yes. The vet treated it with fluids and cooling, and it recovered. That doesn't change the condition I found it in at the time.\""), .cross("Did you see anyone kick the bowl over?", "\"No. I only saw an empty bowl. I can't tell you whether it ran dry on its own or was tipped by someone.\""), .cross("Was there any sign the bowl had been knocked over?", "\"The bowl was sitting upright, and there was no wet patch on the dirt nearby. I can't say that proves it wasn't kicked, only that I didn't see signs of it.\""), .cross("Did the dog look underfed or abused otherwise?", "\"No. It was a healthy weight, with no wounds. The only problem I found was the heat and the lack of water and shade.\""), .cross("You didn't know what time the defendant left that morning, did you?", "\"Only what {D.he} told me, that it was about 7 a.m. I didn't have any independent record of when the dog was last checked.\"")],
        theory: ("{D} left a dog chained in the sun with no water.", "A full bowl in the morning and a bad day."),
        allocution: "\"I thought the bowl was enough. I'm sorry.\"",
        truths: ("A neighbor said the dog had been without water for days that week.", "A neighbor's boy admitted kicking over the bowl while {DL} was at work."),
        defendant: [.direct("Tell us about your dog.", "\"The hound is mine, and I've had it for several years. It lives mostly in the yard, and I feed it twice a day and make sure it has water.\""), .direct("What did you do for the dog the morning of this incident?", "\"I filled the bowl right before I left for work at 7. I always do that, and I remember topping it off because I knew it would be hot.\""), .direct("Why was the dog chained instead of in the pen?", "\"The pen fence has a gap I haven't fixed, and the dog gets out. The chain kept it in the yard, and I thought the post would give shade later.\""), .direct("Do you have any idea how the bowl got empty?", "\"The neighbor's kids have been rough with it before. I think somebody tipped it, but I wasn't there, and I can't say who it was.\""), .direct("What did you do when you heard from animal control?", "\"I left work right away and met them at the vet. I paid the bill and brought the dog home when it was cleared to leave.\""), .direct("What have you changed since then?", "\"I moved the chain to a spot by the porch with real shade and put in a heavy bowl that can't tip. I should have done that before.\""), .cross("The post had no shade, did it?", "\"Not much, no. The morning sun is on the other side and I assumed the chain reached the porch roof shade, which turned out to be wrong.\""), .cross("It was 97 degrees, and you went to work knowing that?", "\"I knew it would be hot and filled the bowl for that reason. I realize now a full bowl wasn't enough if something happened to it.\""), .cross("You didn't have anyone check on the dog during the day, did you?", "\"No. I was at work all day and I trusted the water and the chain. I should have asked a neighbor to look in.\""), .cross("Isn't it true your neighbor said the dog had gone without water other days?", "\"That's what a neighbor says. I disagree, but I know I can't prove what happened on days I wasn't home.\""), .cross("You can't prove the bowl was kicked over, can you?", "\"I can't. I'm told a neighbor's kid might have done it, but I don't have a recording or a witness I can bring in.\"")],
        openings: ("On a 97 degree afternoon, animal control found {D}'s hound chained to a post in the yard, panting and lethargic, with an empty bowl and no shade within reach. The vet found heat exhaustion, and the State will show {D} left that animal that way while at work.", "{D} filled a full bowl at seven that morning and went to work. The defense says a neighbor's child tipped it over later, and the State cannot show {D} knew the dog was without water."),
        closings: ("An empty bowl, a chain that reached no shade, and a lethargic dog in 97 degree heat tell the same story. The vet's report confirms the harm, and the person responsible for the dog was {D}, not the neighbors.", "A full bowl at 7 a.m., a good-weight dog with no wounds, and a bowl that was found sitting upright after a neighbor's child had a history of mischief. The State has not shown {D} knowingly left the dog without water."),
        timeline: [(0, "7 a.m.: {DL} leaves for work."), (0, "2 p.m.: a neighbor calls animal control."), (0, "3 p.m.: the dog is taken to the vet.")],
        identified: "A neighbor's call to animal control.",
        mood: .wantsConviction)

    static let hitAndRunBumper = SmallCases.make(
        key: "story.hitAndRunBumper",
        category: .traffic,
        headlines: ["Driver Backed Into Parked Car and Left", "Hit-and-Run Charge After Parking Lot Collision"],
        law: "hitAndRun",
        spec: "As the driver of a vehicle involved in a crash with an attended vehicle, failed to stop and give identifying information, on {DATE}.",
        ages: 19...70,
        victim: true,
        summary: "{V} sat in a parked car at a drugstore on {DATE} when a pickup backed into it, crushing the rear bumper and fender, and left. {V} wrote down the plate. The truck belongs to {D}. {DL} says {D.he} felt a bump but thought it was a cart and didn't see anyone in the other car.",
        state: [E(.video, 3, "Drugstore Camera", "A pickup backs into the rear of a sedan and drives off."), E(.document, 2, "Plate Record", "The plate on the camera is registered to {D}.")],
        defense: [E(.statement, 1, "A Cart", "{DL} says {D.he} felt a bump and assumed it was a shopping cart.")],
        role: "Police officer",
        exam: [.direct("What were you called to on the afternoon of {DATE}?", "\"Dispatch sent me to a drugstore lot for a hit and run. {V} was waiting there, shaken, next to a sedan with its rear bumper and fender crushed.\""), .direct("What did {V} tell you happened?", "\"{V} was sitting in the parked car when a pickup backed into it, crushing the rear, and then drove away. {V} had written down the plate before it left.\""), .direct("What did the drugstore camera show?", "\"A pickup backing across the lot, striking the back of the parked sedan, pausing for a moment, and then pulling out and leaving. The plate is readable on the footage.\""), .direct("What did you do with the plate?", "\"I ran it. The plate came back registered to {D}, and the truck description matched the camera. I contacted {DL} two days later.\""), .direct("How bad was the damage to the sedan?", "\"The rear bumper was pushed in, the fender was crumpled, and the trunk lid no longer closed properly. It was not a minor scrape and it wasn't a cart bump.\""), .direct("What did {D} say when you spoke with {D.him}?", "\"{DL} said {D.he} felt a bump while backing out, assumed it was a shopping cart, and never saw anyone in the other car.\""), .cross("Did anyone see the defendant get out and look at the sedan?", "\"No. The camera shows the truck pausing a moment and leaving. Nobody on the video gets out to look.\""), .cross("Was {V} injured?", "\"{V} said {V.he} was shaken up and sore later but didn't request an ambulance. I didn't see an injury that needed care at the scene.\""), .cross("Does the footage show the defendant's face at the wheel?", "\"No. The truck is the key piece. The plate and truck are clear, but the driver's face isn't visible from that camera angle.\""), .cross("Did the truck have a working backup camera?", "\"I don't know what the truck's equipment was at the time. {D.He} later brought up a broken camera, and I didn't verify it myself.\""), .cross("Could a driver feel something that big from inside the truck cab?", "\"A driver would feel something. Whether {D.he} thought it was a cart or a car, I can't say from the footage, only that the sedan took a real impact.\"")],
        theory: ("{D} hit an occupied car and drove away.", "A driver who thought he'd hit a cart."),
        allocution: "\"I should have gotten out and looked. I'm sorry.\"",
        truths: ("A bystander saw {DL} look in the mirror and drive off.", "The truck's backup camera was out and the bumper sensor was broken, a mechanic confirmed."),
        defendant: [.direct("What were you doing at the drugstore?", "\"I was picking up a prescription for a relative. I parked, ran in, and was backing out of the space when I felt a bump.\""), .direct("What did you think the bump was?", "\"A shopping cart. The lot was full of carts that afternoon, people leave them loose, and it felt like the bump of rolling over a low curb or cart.\""), .direct("Did you look back to see what you hit?", "\"I glanced in the mirror but didn't see anything strange. I had no clear sight of the back of the sedan because my backup camera didn't work.\""), .direct("Did you see anyone in the sedan?", "\"No. I'd have stopped if I'd seen a person. The window glass was tinted and the sun was low, and I never knew anyone was inside.\""), .direct("How did you learn about the collision?", "\"A deputy called me two days later and told me what the camera showed. I was surprised and I agreed to come in and talk right away.\""), .direct("What is wrong with the truck's backup equipment?", "\"The backup camera has been out for months, and the bumper sensor is broken too. I kept meaning to fix them and hadn't.\""), .cross("You drove off after feeling a bump, correct?", "\"Yes, I felt the bump and drove away. I thought it was minor and had no reason to believe there was a car attached to it.\""), .cross("You looked in the mirror, so you knew something had happened?", "\"I knew I'd hit something small. I didn't know it was a car, and the mirror didn't show me anything that told me to stop.\""), .cross("Do you know how big a sedan's rear bumper is compared to a cart?", "\"I do now. At the time I was in a hurry and I didn't think that through, and I'm not offering that as an excuse.\""), .cross("Did you check your truck's rear after that?", "\"I didn't look. I looked later and saw a scuff on the bumper, but I put it down to the cart I thought I'd bumped.\""), .cross("You didn't leave a note or call anyone?", "\"No, because I thought nothing important had happened. Had I known it was a car with a person in it, I'd have stayed.\"")],
        openings: ("A pickup backed across a drugstore lot, crushed the rear of a parked sedan with {V} sitting inside, and drove off. The camera shows the impact and the plate, and the plate leads to {D}.", "{D} felt a bump, thought it was a shopping cart, and could not see the sedan because the backup camera and sensors on the truck were broken. The State must prove {D} knew a car had been hit, not just that the truck was involved."),
        closings: ("The truck, the plate, and the damage line up. A driver who feels a collision that crushes a fender and trunk and then leaves without looking has failed the duty to stop, and {D} was that driver.", "Nothing on the video shows {D} seeing a person or a car. The backup camera was out and the sensor was broken, and a bump taken for a cart is a mistake, not the knowing departure the charge requires."),
        timeline: [(0, "Afternoon: the pickup backs into the sedan."), (0, "{V} notes the plate and calls deputies."), (2, "{DL} is traced through the plate.")],
        identified: "{V}'s plate note and the drugstore camera.",
        genders: ["D": .male])

    static let badCheckFeed = SmallCases.make(
        key: "story.badCheckFeed",
        category: .whiteCollar,
        headlines: ["Farmer Wrote $380 Check on Closed Account", "Feed Store Says Check Bounced and Calls Went Unanswered"],
        law: "uttering",
        spec: "Uttered a check for $380 drawn on an account {D} knew was closed, to a feed store, on {DATE}.",
        ages: 28...66,
        victim: false,
        summary: "{D} wrote a $380 check to a feed store for hay and sweet feed on {DATE}. The check came back marked 'account closed.' The bank had closed the account four months earlier after repeated overdrafts and mailed notice. The store left three messages. {DL} says the bank never told {D.him} and {D.he} was waiting on a government payment.",
        state: [E(.document, 3, "Returned Check", "Marked 'account closed'; a bank letter four months earlier closing the account."), E(.document, 2, "Store Log", "Three messages left over two weeks; none returned.")],
        defense: [E(.document, 2, "Pending Payment", "A government check for $410 was due the following week.")],
        role: "Feed store owner",
        exam: [.direct("What does your store sell?", "\"We're a feed and farm supply store. Hay, sweet feed, mineral blocks, and tack for horses and cattle, and most of our customers are regulars from the surrounding farms.\""), .direct("What did {D} purchase on the day in question?", "\"Hay and sweet feed on {DATE}. {D} loaded it into a truck and wrote a check for $380 at the counter.\""), .direct("What happened when you deposited that check?", "\"It came back from the bank marked account closed. The bank's letter, which came with it, showed the account had been closed four months before the purchase.\""), .direct("What did you do after the check bounced?", "\"I left three messages on {D.his} phone over about two weeks, asking for payment. I wrote each of them in our log, and none was returned.\""), .direct("Did the defendant ever come in to make good?", "\"No. After two weeks of silence, I turned the returned check over to the sheriff's office as a bad check.\""), .direct("How does a loss like this affect the store?", "\"A $380 loss hurts a small store, because feed is bought up front from the supplier. We carry the cost until the customer pays, and sometimes they never do.\""), .cross("Isn't it true the defendant has been a regular customer for years?", "\"Yes. {D.He} has bought feed here for years and paid every time I can remember. That's why this one surprised me.\""), .cross("Did the defendant ever try to hide when you called?", "\"I can't say. I left messages, and nobody called back. I don't know whether the phone was working or whether the messages were heard.\""), .cross("Do you know whether the bank ever told the defendant the account was closed?", "\"The bank's letter says it mailed notice. I have no way to know whether {D.he} received it, or where it was addressed.\""), .cross("When you take a check, do you check the account status?", "\"We don't. We take checks from regulars on trust and rely on the bank to clear them. Nothing about the check looked wrong to me.\""), .cross("Did {D} offer any explanation when you finally reached {D.him}?", "\"I never reached {D.him} on the phone. Any explanation came later through the deputy, not to me directly.\"")],
        theory: ("{D} wrote a check on an account that had been closed for months.", "A regular customer who didn't get the bank's letter."),
        allocution: "\"I should have checked. I paid it back.\"",
        truths: ("{DL}'s phone held a bank notice photo from four months earlier.", "The bank had mailed its notice to a farm box {DL} no longer used."),
        defendant: [.direct("Why did you write a check to the feed store?", "\"I needed hay and feed for my animals, and I've written checks there for years. I had no idea the account had been shut down.\""), .direct("When did you last use that account?", "\"Before that day, I hadn't used it in a while. I'd been paying cash, and I kept the checkbook for bigger purchases like feed.\""), .direct("Did the bank ever contact you about the account?", "\"Not that I know of. I never saw a letter or a call, and I would have stopped writing checks right away if I had.\""), .direct("What were you expecting the money to come from?", "\"A government payment was due, $410, the following week. I figured it would cover the $380 once it came, and I planned to pay the store.\""), .direct("Why didn't you return the store's calls?", "\"My phone was acting up and I missed some. The messages that did reach me, I meant to answer and never got around to, and I'm sorry about that.\""), .direct("What have you done about it since?", "\"I want to pay the store back in full. I've set aside the money and I'm willing to bring it in today if the store will take it.\""), .cross("You'd had overdrafts on that account before it closed, hadn't you?", "\"Yes, there were some. I'd gone over a few times, and I know the bank wasn't pleased, but I didn't think that meant it would shut the account.\""), .cross("So you knew the balance was low when you wrote the check?", "\"I knew it was tight. I was counting on the deposit that was coming, so I wasn't sure of the balance when I wrote it.\""), .cross("You didn't check the balance or your statements before writing it?", "\"I didn't. I should have, and I know that now. I was in a hurry, loading the truck, and I just wrote it.\""), .cross("Isn't it true the store called you three times?", "\"Yes, I know they called. I let those go and that was a mistake. I was embarrassed and didn't want to talk until I had the money.\""), .cross("You've kept a photo of a bank notice on your phone, haven't you?", "\"There's a photo on my phone of a bank notice from months ago. I didn't read it carefully and I didn't connect it to this check.\"")],
        openings: ("{D} loaded $380 worth of hay and feed into a truck and paid with a check on an account the bank had closed four months earlier. The store left three messages, none was returned, and the State will show the check was worthless from the start.", "This is a longtime feed store customer who never got the bank's notice and was waiting on a government payment. The defense says {D} had no idea the account was closed, and a bounced check alone is not a crime."),
        closings: ("The account was closed four months before the check, the bank's notice was sent, and three calls from the store went unanswered. {D} wrote a check that could never be paid, and the silence afterward speaks for itself.", "{D} paid this store for years without trouble, never saw a closing notice, and expected a payment to arrive within days. The State must prove {D} knew the account was closed, and being careless with a checkbook is not the same thing."),
        timeline: [(-120, "The bank closes the account."), (0, "{DL} writes the check at the feed store."), (14, "The store turns the check over to the sheriff.")],
        identified: "The store owner's complaint.",
        genders: ["D": .male])

    static let facebookThreat = SmallCases.make(
        key: "story.facebookThreat",
        category: .publicOrder,
        headlines: ["Man Posted Threat to Burn Neighbor's Truck", "Post Said 'I'll Light It Up'; Neighbor Called Deputies"],
        law: "communicatingThreats",
        spec: "Willfully threatened to damage the property of {V} by fire, in a manner a reasonable person would believe would be carried out, on {DATE}.",
        ages: 24...62,
        victim: true,
        summary: "After {V} complained about {D}'s barking dogs, {D} posted on a neighborhood Facebook group on {DATE}: \"Tell {V} I'll light that truck up if the complaints don't stop.\" A dozen neighbors saw it. {V} showed it to deputies the next morning. {DL} says it was a joke made in front of friends and he deleted it within an hour.",
        state: [E(.digital, 3, "The Post", "'Tell {V} I'll light that truck up if the complaints don't stop.' Twelve reactions."), E(.statement, 2, "Neighbors", "Three neighbors read it and believed it was serious.")],
        defense: [E(.statement, 1, "Deleted", "{DL} removed the post within an hour.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did you become involved in this complaint?", "\"{V} came to the sheriff's office the morning after the post went up and showed me a screenshot from a neighborhood Facebook group. I took a report on the spot.\""), .direct("What did the post say?", "\"It said, Tell {V} I'll light that truck up if the complaints don't stop. It was posted under {D}'s own name, on a group with several dozen local members.\""), .direct("What was the background to the post?", "\"{V} had complained to the county three days earlier about {DL}'s barking dogs. {DL} had been told about the complaint before the post appeared.\""), .direct("How many people saw it?", "\"Twelve people reacted and at least three neighbors read it and told us they took it seriously. One said {V}'s truck is parked in the driveway every night.\""), .direct("How did {V} react when showing it to you?", "\"{V} was frightened, said {V.he} had parked the truck inside the garage ever since, and asked whether it was safe to stay home overnight.\""), .direct("What did you do after taking the report?", "\"I spoke to {DL} and confirmed the post was {DL}'s. I also asked a neighbor to forward a copy because the post had been deleted by the time we looked.\""), .cross("The post was deleted within an hour, correct?", "\"Yes, by the time I looked it had been removed. That is why I rely on the screenshot {V} took, along with the neighbors' accounts of reading it.\""), .cross("Did {D} ever say anything to {V} directly?", "\"Not that I'm aware of. The only communication I found was the group post. There was no phone call and no confrontation.\""), .cross("Did anyone see the defendant near {V}'s truck?", "\"No. Nobody told me {DL} was seen near the truck, and the truck was never touched or damaged.\""), .cross("Isn't it true the post sounds like a figure of speech?", "\"It could be read that way. I took it at face value because it names a specific vehicle and an action, but I understand why it can be called a joke.\""), .cross("Did the neighbors all agree it was a real threat?", "\"Three said they took it seriously, but I did not poll the other nine who reacted. I can't say what everyone thought.\"")],
        theory: ("{D} publicly threatened to burn {V}'s truck.", "A joke posted in a heated moment and deleted."),
        allocution: "\"It was a stupid post. I'm sorry I scared {V.him}.\"",
        truths: ("{DL} had bought gasoline cans the day before, a receipt showed.", "The post was a quote from a movie {DL}'s friends had been quoting all week."),
        defendant: [.direct("What led you to write that post?", "\"I was angry. The county had just come to my door over my dogs, and I wanted to vent to friends in the group about the complaint.\""), .direct("What did you mean by it?", "\"It was a joke, a line I and some friends had been quoting from a movie all week. I didn't mean it as a real plan to burn anything.\""), .direct("Why did you take it down so quickly?", "\"A friend messaged me within minutes saying it looked bad. I agreed and deleted it. I never wanted it to scare anyone.\""), .direct("Have you ever damaged someone's vehicle or property?", "\"Never. I've had my dogs complained about before, but I've never done anything to a neighbor's property in all my years here.\""), .direct("What would you say to {V} now?", "\"I'm sorry for the way it sounded. I should have kept my frustration to myself instead of posting it where the whole neighborhood could read it.\""), .direct("What have you done about the barking complaint?", "\"I put the dogs inside at night and added a fence so they stay off the road. I'm trying to be a better neighbor.\""), .cross("You named {V}'s truck specifically, didn't you?", "\"Yes, the post names the truck. I said it to make my point, and I see now how that reads when it's about a specific vehicle.\""), .cross("Did you buy gasoline cans the day before?", "\"I did buy gas cans, for my mower and a generator. That was ordinary and had nothing to do with {V}.\""), .cross("It was posted where {V}'s neighbors could read it?", "\"Yes, a neighborhood group with about forty people. I didn't think about how it would land with {V} specifically.\""), .cross("You were angry at {V} when you wrote it?", "\"I was upset about the complaint, yes. I wasn't thinking clearly, and I let it spill into a post I regretted.\""), .cross("Did you apologize to {V} directly?", "\"Not yet. I wasn't sure it was welcome after the deputies got involved, but I'd say it to {V.him} if asked.\"")],
        openings: ("Three days after {V} complained about {D}'s barking dogs, {D} posted to a neighborhood group that {D} would light {V}'s truck up if the complaints did not stop. Twelve neighbors saw it, three took it seriously, and the State will show it was a true threat to burn property.", "This was a joke in a movie voice, posted in a heated moment and deleted within the hour. The defense says no one was approached, nothing was touched, and an angry post is not a true threat."),
        closings: ("The post names {V}, names the truck, and names the act, and it followed a complaint {D} was angry about. Neighbors read it and believed it, and a threat is judged by how a reasonable person would take it.", "Nobody saw {D} near that truck, the post was gone in an hour, and the words matched a line friends had been quoting all week. A bad joke posted in anger is not the true threat the statute requires."),
        timeline: [(-3, "{V} complains about the dogs."), (0, "{DL} posts the message."), (1, "{V} shows deputies the post.")],
        identified: "{V}'s screenshot of the post.",
        genders: ["D": .male])

    static let repeatedTexts = SmallCases.make(
        key: "story.repeatedTexts",
        category: .robbery,
        headlines: ["Man Sent 200 Texts to Ex After Being Blocked", "Stalking Charge After Weeks of Messages"],
        law: "stalking",
        threshold: 6,
        spec: "Willfully on more than one occasion harassed {V} without legal purpose, including 212 text messages and calls after being told to stop, on {DATE}.",
        ages: 21...55,
        victim: true,
        summary: "{V} ended a relationship with {D} in the spring and told {D} to stop contacting {V.him}. Over the next six weeks {D} sent 212 text messages from three different numbers, left voicemails, and appeared once outside {V}'s workplace. {V} blocked each number and kept screenshots. {DL} says {D.he} never threatened {V.him} and only wanted closure.",
        state: [E(.digital, 3, "Text Messages", "212 messages in six weeks from three numbers, many at night; two say 'I know where you work.'"), E(.document, 2, "Phone Log", "Dozens of calls and voicemails, each after a block.")],
        defense: [E(.statement, 1, "Closure", "{DL} says {D.he} never meant to frighten anyone.")],
        role: "Sheriff's detective",
        exam: [.direct("What did you find when you reviewed {V}'s phone?", "\"I found 212 text messages over about six weeks, coming from three different phone numbers, along with a stack of voicemails and a long call log.\""), .direct("How did the messages change over time?", "\"They started as pleading and apologetic, then kept coming at night. Two of the later ones said 'I know where you work,' and {V} says {D} showed up outside the workplace once.\""), .direct("What did {V} do in response?", "\"{V} blocked each number as it appeared and saved screenshots of everything. The new numbers always arrived right after a block, and {V} then made a report.\""), .direct("How many of the messages were sent at night, and what did that pattern show?", "\"A large share of them were sent between ten at night and two in the morning. The pattern showed someone checking the phone constantly, and the timing lined up with each time a number was blocked.\""), .direct("What did the voicemails contain?", "\"Mostly pleading and apologies, and a few long ones where the caller said {V} owed an explanation. Each one came from a number that had been blocked or a new number right afterward.\""), .direct("What happened at the workplace?", "\"{V} saw {DL} standing outside the entrance at the end of a shift and went back inside to call a coworker. {DL} left before anyone from the business approached.\""), .cross("None of those messages contain a threat of violence, do they?", "\"Not in so many words. There is no message saying {DL} would hurt {V.him}. The concern is the pattern and the line about the workplace.\""), .cross("Isn't it true {D} said {D.he} wanted closure?", "\"Yes, that's the explanation {DL} gave. But {V} had already said to stop, and the contact continued for weeks after that.\""), .cross("How many times did the defendant appear in person?", "\"Only once that we can document, outside the workplace. The rest of the contact was by phone and text.\""), .cross("Did you recover any message saying the defendant would hurt {V}?", "\"No. The closest are the two that say 'I know where you work,' and the second of those arrived the same week as the appearance outside the building.\""), .cross("Did {V} ever say the defendant had been violent in the past?", "\"Not to me. {V} described the relationship as ordinary until it ended, and what frightened {V} was the volume and the new numbers.\"")],
        theory: ("{D} kept contacting {V} after being told no, from new numbers, and showed up at work.", "A heartbroken ex who sent messages and never hurt anyone."),
        allocution: "\"I couldn't let go. I'm sorry I scared {V.him}.\"",
        truths: ("{DL} had bought a second phone just to get around the blocks.", "{DL}'s therapist said the messages were part of a grief response and {D.he} had begun treatment."),
        defendant: [.direct("Why did you send so many messages?", "\"I was hurting. The breakup felt sudden and I wanted to understand it. I kept hoping for one conversation that would give me some closure.\""), .direct("Did you ever intend to frighten {V}?", "\"No. I never threatened {V.him} and never wanted to scare {V.him}. I just could not stop reaching out, and I see now how it felt on the other end.\""), .direct("Why did you go to the workplace?", "\"I went once, thinking I could catch {V.him} for five minutes and talk. I stayed outside, I did not go in, and I left when I saw {V.him}.\""), .direct("What was happening in your life during those six weeks?", "\"I had lost my sense of routine. I was sleeping badly, missing work, and the messages came in bursts whenever I felt especially low.\""), .direct("Did you read any messages back to yourself before you sent them?", "\"Honestly no. I sent them in the moment, usually late, and I regret that most of them sound the way they do.\""), .direct("What did you think when the first number was blocked?", "\"I felt rejected, and I wanted a way to explain myself. I should have understood that being blocked was an answer.\""), .cross("You knew you were being blocked, didn't you?", "\"Yes, I knew. I understood that every time a message failed, it was a signal, and I kept finding another way anyway.\""), .cross("Why use three different numbers?", "\"I didn't think of it as hiding. I wanted one more chance to be heard, but I can see why it looks like I was getting around the block.\""), .cross("What did you mean by 'I know where you work'?", "\"I meant it as a sad thing, that I knew where to find {V.him} and was not going to. I understand now how it reads. It reads wrong.\""), .cross("You sent two messages saying 'I know where you work.' What was the purpose of that?", "\"I wrote it as a sad statement, not a warning. I can see now that sent at that hour, to someone who wanted no contact, it read as something else.\""), .cross("You showed up outside {V}'s job after being blocked everywhere. Wasn't that the point, to make {V.him} see you?", "\"I wanted to talk once in person. I stayed on the sidewalk, left when {V.he} went inside, and have not been back.\"")],
        openings: ("Two hundred twelve messages in six weeks, from three phone numbers, after {V} said to stop. The State will show the screenshots, the call log, and the night {D} appeared outside {V}'s workplace.", "This case is about a breakup, not a threat. The defense will show that {D} never used violence or threatening words and that the messages came from grief and not from a plan to scare anyone."),
        closings: ("{V} said stop. {D} kept going, switched phone numbers, and sent a message saying {D.he} knew where {V} worked. The law protects a person's right to be left alone, and {V} was not.", "There is no threat in these messages and no act of violence. There is a person who was heartbroken, who has accepted help, and who never meant to hurt anyone. That is not harassment without legal purpose."),
        timeline: [(-45, "The relationship ends and {V} asks {D} to stop."), (-20, "{DL} starts using other numbers."), (0, "{V} reports the messages to deputies.")],
        identified: "{V}'s screenshots.",
        mood: .sympathetic,
        genders: ["D": .male])

    static let drunkPorch = SmallCases.make(
        key: "story.drunkPorch",
        category: .property,
        headlines: ["Man Found Asleep on Neighbor's Porch Swing at 4 A.M.", "Trespass Charge After a Wrong Turn Home"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V} after being notified not to enter, on {DATE}.",
        ages: 22...62,
        victim: true,
        summary: "{V} woke at 4 a.m. on {DATE} to a noise on the front porch and found {D} asleep on the porch swing with a coat over {D.his} head. {D} smelled of beer. {V} had told {D} the week before to stay off {V.his} property after an argument over a fence. {DL} says {D.he} thought it was {D.his} own porch, since the houses look alike.",
        state: [E(.statement, 3, "Earlier Warning", "{V} says {V.he} told {D} to stay off the property a week earlier."), E(.video, 2, "Porch Camera", "{D} stumbles up the steps at 3:30 a.m. and lies down.")],
        defense: [E(.statement, 1, "Same Floor Plan", "The two houses are identical models three doors apart.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to on the morning of {DATE}?", "\"{V} called about 4:10 a.m. to report someone asleep on the front porch. I arrived and found {D} on the porch swing with a coat over {D.his} head.\""), .direct("What condition was {D} in?", "\"Asleep, then groggy and confused when I woke {DL}. There was a strong smell of beer on {DL}'s breath, and {DL} had trouble standing at first.\""), .direct("What did {V} tell you about the defendant?", "\"{V} said that a week earlier, after an argument about a fence, {V.he} told {DL} to stay off the property. {V} was frightened to find {DL} there.\""), .direct("Does the porch camera help your investigation?", "\"It shows {DL} stumbling up the steps at 3:30 a.m. and lying down on the swing. It doesn't show how {DL} got to the street in front of the house.\""), .direct("How far is the defendant's own house from the porch?", "\"Three doors down on the same street. The two homes are the same model, with the same porch layout and nearly the same paint color.\""), .direct("What did you do?", "\"I arrested {DL} for trespassing after {V} said {V.he} wanted to press the issue, and I arranged for a ride so {DL} wasn't driving.\""), .cross("Isn't it true the houses look nearly identical?", "\"Yes. They're matching models three doors apart, and in the dark I could see how someone in {DL}'s state could mix them up.\""), .cross("Was the defendant's porch light on that night?", "\"I noticed it was out when I walked down to {D.his} house later. The street was fairly dark overall.\""), .cross("Did the defendant try to enter {V}'s house?", "\"No. {DL} never touched the door. {DL} just lay down on the porch swing and fell asleep.\""), .cross("Did {D} damage anything or take anything?", "\"Nothing. The porch swing was fine and there was nothing missing. {D.He} was only asleep on it.\""), .cross("What did the defendant say when you woke {D.him}?", "\"{D.He} said it was {D.his} porch and seemed truly puzzled. I didn't hear anything that sounded like a lie, but I couldn't be sure given the beer.\"")],
        theory: ("{D} had been told to stay away and entered the porch anyway.", "A drunk man who mistook a neighbor's identical house for his own."),
        allocution: "\"I was drunk and went to the wrong house. I'm sorry.\"",
        truths: ("{DL}'s keys were in his pocket and he had passed his own door to reach the porch.", "{DL}'s own porch light was out and the street was dark."),
        defendant: [.direct("What do you remember about that night?", "\"I'd been out with friends and had some beers. I walked home down the street, and I don't remember much of the last few minutes.\""), .direct("Where did you think you were when you lay down?", "\"On my own porch. It looked like my house and it had the swing in the same place, so I got comfortable and fell asleep.\""), .direct("Did you know {V} had told you to stay off the property?", "\"Yes, after the fence argument. I never meant to go back. If I had known it was {V}'s porch, I wouldn't have gone near it.\""), .direct("Where were your keys?", "\"In my pocket. I didn't try the door at all, because I thought I'd just sit and rest for a minute before going in.\""), .direct("What was the lighting like on the street?", "\"Dark. My own porch light had been out for days, and the street lamp down the road doesn't reach that stretch.\""), .direct("How did you feel when you woke up?", "\"Confused and embarrassed. When I realized it was {V}'s house, I wanted to apologize right away, but the deputy was already there.\""), .cross("You'd been drinking heavily, hadn't you?", "\"I'd had several beers. I wasn't falling down, but I'd say I was drunk enough to lose track of where I was.\""), .cross("You passed your own door to reach the porch?", "\"Apparently, yes. Three doors is a short distance and I walked past mine without noticing, which sounds strange but that's what happened.\""), .cross("The fence argument was still on your mind?", "\"It had been a week, and I'd tried not to think about it. I'm not going to say I was fond of {V} at that point.\""), .cross("You knew which house was {V}'s, didn't you?", "\"Of course. I know where {V} lives. That's why it makes no sense that I'd walk there on purpose after being told to stay away.\""), .cross("Did you check the number on the house?", "\"No. I didn't look at the number or the mailbox. I recognized the shape of the porch and assumed it was mine.\"")],
        openings: ("A week after {V} told {D} to stay off the property, the porch camera caught {D} stumbling up {V}'s steps at 3:30 a.m. and lying down. The State will show {D} was warned, had been drinking, and entered land {D} knew was off limits.", "{D} had been out with friends and walked to the wrong house, one of two identical models three doors apart, on a dark street with a dead porch light. The defense says {D} fell asleep on what {D} honestly believed was {D.his} own porch."),
        closings: ("{V} told {D} in plain words to stay off the property, and a week later {D} was on {V}'s porch at 3:30 in the morning. Being drunk may explain the mistake, but it does not excuse entering after a warning.", "The houses are twin models, the street was dark, and {D}'s own porch light was out. {D} touched nothing, tried no door, and simply fell asleep, which is what a person who thinks they are home does."),
        timeline: [(-7, "{V} warns {D} to stay off the property."), (0, "3:30 a.m.: {DL} climbs the steps."), (0, "4:10 a.m.: {V} calls deputies.")],
        identified: "{V}'s call to deputies.",
        genders: ["D": .male])

    static let mailTheft = SmallCases.make(
        key: "story.mailTheft",
        category: .property,
        headlines: ["Mail From Six Boxes Found in Man's Car", "Postal Inspector Says Man Took Mail Along Rural Route"],
        law: "misdLarceny",
        spec: "Stole mail belonging to several residents of a rural route, valued at less than $1,000, on {DATE}.",
        ages: 18...55,
        victim: false,
        summary: "Six residents on a rural route reported missing mail over two weeks, including a birthday card with $50 and a pharmacy package. A deputy stopped {D} for a headlight on {DATE} and found nineteen pieces of opened mail addressed to other people in a grocery bag in {D}'s back seat. {DL} says {D.he} found the bag at a mailbox cluster and was bringing it to the post office.",
        state: [E(.physical, 3, "The Mail", "Nineteen pieces of mail, most opened, addressed to six residents.", .search), E(.document, 2, "Residents' Reports", "Six residents report missing mail on the same route.")],
        defense: [E(.statement, 1, "Found Bag", "{DL} says the bag was on the ground by the mailboxes.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop {D}'s vehicle?", "\"I saw a headlight out on a rural road and made a routine traffic stop. During the stop I noticed a grocery bag in the back seat that was stuffed with envelopes.\""), .direct("What was inside the bag?", "\"Nineteen pieces of mail, most of them opened, addressed to six different residents on the same rural route, including a pharmacy package.\""), .direct("What did the defendant say about the mail?", "\"{D} told me the bag was found by a mailbox cluster and that {D.he} was on the way to take it to the post office.\""), .direct("What time and where did you stop the vehicle?", "\"It was in the evening on a rural route, near the mailbox clusters where the reports had come from. I stopped {D.him} for the headlight and noticed the grocery bag as I approached.\""), .direct("How did the mail in the bag look to you?", "\"Nineteen pieces, most slit open along the top edge, addressed to at least six different households on that same route. A pharmacy package and a birthday card envelope were in the pile.\""), .direct("What happened with the mail after the stop?", "\"I photographed it, logged each piece, and a postal inspector took custody. The inspector matched the names to the six residents who had reported mail missing.\""), .cross("No one saw the defendant take any of this mail, did they?", "\"No. I have no witness who saw {DL} at a mailbox, and no video of that. What I have is the mail in {D.his} car.\""), .cross("Was the defendant cooperative during the stop?", "\"Yes. {D.He} was polite and answered my questions. {D.He} did not try to hide the bag or drive off when I walked up.\""), .cross("If the defendant were heading to the post office, would you expect the route to go that way?", "\"I can't say for sure. The post office is not far, and the direction {DL} was traveling could have fit, but it was a different way than I would have gone.\""), .cross("Did {D} try to hide the bag when you stopped the car?", "\"No. The bag was on the back seat in plain view, and {D.he} pointed to it before I asked.\""), .cross("Were any of the opened items found on the defendant's person?", "\"No. Everything was inside the bag, and I did not find any cash or cards from the envelopes on {DL}.\"")],
        theory: ("{D} took mail from rural boxes and opened it.", "A finder with a bag of mail and good intentions."),
        allocution: "\"I opened a couple to find who they were for. I know how that looks.\"",
        truths: ("A pharmacy card from a resident's package was found in {DL}'s wallet.", "A teenager later admitted dropping the bag at the mailboxes after stealing it."),
        defendant: [.direct("Where did you get the bag of mail?", "\"I found a grocery bag on the ground by a cluster of mailboxes. It was full of envelopes and packages, and I figured someone had dropped it.\""), .direct("Why did you open some of the envelopes?", "\"I wanted to find names and addresses so I could return it. I opened a few of them looking for something that would tell me who it belonged to.\""), .direct("What were you planning to do with the bag?", "\"I was planning to take it to the post office. I was on my way when the deputy pulled me over for the headlight.\""), .direct("Where exactly did you see the bag?", "\"On the gravel at the edge of the mailbox cluster on my usual way home. It looked like someone had dropped it in a hurry, and a few envelopes were sticking out the top.\""), .direct("What did you do when you picked it up?", "\"I looked inside, saw it was mail for several neighbors, and decided to take it to the post office. I put it on the back seat so it wouldn't blow around.\""), .direct("Why were some envelopes opened?", "\"Some were already torn when I found them. I opened a couple more at a stop sign, hoping to find a return address or phone number.\""), .cross("Nineteen pieces were opened. That's more than a few, isn't it?", "\"It might have been more than I remember. I was going through them quickly, and I guess I opened more than I wish I had.\""), .cross("If you meant to return it, why not leave it at a mailbox or call someone?", "\"I did not think about leaving the bag at a mailbox. It seemed easier to take it to the post office myself, and I thought that was the right thing to do.\""), .cross("The route has six victims over two weeks. A bag appearing the same day you were driving by?", "\"I know how it sounds. All I can tell you is that it was on the ground when I got there, and I picked it up.\""), .cross("You looked inside envelopes at a stop sign instead of driving straight to the post office?", "\"I know that was a bad decision. I was trying to work out who owned it, and I didn't think about how it would look.\""), .cross("You could have called the sheriff's office from the roadside. Why didn't you?", "\"It didn't occur to me. I figured the post office would know what to do, and I was already on my way there.\"")],
        openings: ("For two weeks, six households on a rural route lost mail. Then a deputy stopped {D} for a headlight and found nineteen pieces of other people's mail, most of them opened, in a grocery bag in the back seat.", "A bag of mail was lying on the ground by a mailbox cluster. The defense will show a person who picked it up, opened some envelopes to find names, and was on the way to the post office."),
        closings: ("Nineteen pieces of mail, opened, addressed to six neighbors, sitting in {D}'s back seat. People who are returning mail do not open it, and people who are driving to the post office do not wait to be stopped.", "{D} found a bag and was doing what a decent person does, trying to get it back to its owners. No one saw {D} touch a single mailbox. Suspicion is not proof beyond a reasonable doubt."),
        timeline: [(-14, "The first resident reports missing mail."), (0, "{DL} stopped for a headlight; the bag is found."), (1, "A postal inspector links the reports.")],
        identified: "A deputy's traffic stop.",
        genders: ["D": .male])

    static let gasCanSiphon = SmallCases.make(
        key: "story.gasCanSiphon",
        category: .property,
        headlines: ["Man Caught Siphoning Gas From Neighbor's Truck", "Hose and Gas Can Found Under Truck at Dawn"],
        law: "misdLarceny",
        spec: "Stole about twenty gallons of gasoline valued at $74 from a pickup truck belonging to {V}, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "{V} came out at 5:40 a.m. on {DATE} and found {D} crouched at {V}'s truck with a hose in the tank and a five-gallon can. {D} said {D.he} had run out of gas and was borrowing a little. {V} found the tank nearly empty and two more filled cans in {D}'s car. {DL} says {V} had lent {D.him} gas before.",
        state: [E(.physical, 3, "Cans and Hose", "A hose in the tank, a five-gallon can, and two full cans in {D}'s car.", .search), E(.statement, 2, "{V}'s Account", "{V} says {V.he} never agreed to lend gas that morning.")],
        defense: [E(.statement, 1, "Prior Loan", "{DL} says {V} had lent {D.him} gas once before.")],
        role: "Sheriff's deputy",
        exam: [.direct("What happened at the scene that morning?", "\"I was dispatched around 6 a.m. to {V}'s address. {V} told me that at 5:40 {V.he} found {D} crouched at the truck with a hose in the tank and a can beneath.\""), .direct("What did you find at the truck?", "\"A hose in the fuel tank, a five-gallon can by the bumper, and the truck's gauge sitting on empty. {V} said the tank had been about three-quarters full the night before.\""), .direct("What did you find in {D}'s car?", "\"Two more five-gallon cans, both full, in the back seat. That made about fifteen gallons of gas, beyond what {D.he} might need to fill one tank.\""), .direct("How much gas was taken, in your estimate?", "\"Roughly twenty gallons across all the containers, by {V}'s count of what the tank held. That's a significant amount at current prices.\""), .direct("What did the defendant say at the scene?", "\"{D.He} said {D.he} had run out of gas and was borrowing a little, and that {V} had lent {D.him} gas once before.\""), .direct("How did {V} respond to that?", "\"{V} said {V.he} never agreed to lend anything that morning and certainly not before six a.m. in the dark. {V} wanted to press charges.\""), .cross("Isn't it true {V} had lent the defendant gas before?", "\"{V} acknowledged once, some time ago. {V} said that time was by asking and in daylight, and not by crouching beside the truck before sunrise.\""), .cross("Did you see the defendant actually run off or hide?", "\"No. {D.He} stayed at the truck and talked to me. {D.He} didn't try to leave or give a false name.\""), .cross("Did the defendant damage the truck?", "\"Not that I saw. The tank cap was off and fuel had spilled on the pavement, but there was no damage to the vehicle itself.\""), .cross("Was {V}'s statement about the tank level based on a gauge reading?", "\"It was based on what {V} remembered from the night before. There's no record of the exact amount in the tank.\""), .cross("Did any neighbor tell you {V} said take what you need?", "\"A neighbor told me {V} said something like that two weeks earlier. I couldn't confirm it with {V}, who denied agreeing to any such arrangement.\"")],
        theory: ("{D} siphoned twenty gallons of gas from {V}'s truck at dawn.", "A neighbor who had borrowed gas before and asked too late."),
        allocution: "\"I was out of gas and money. I should have knocked.\"",
        truths: ("A camera across the street showed {DL} making three trips to the truck before dawn.", "{V} had told {DL} 'take what you need' two weeks earlier, a neighbor recalled."),
        defendant: [.direct("What were you doing at {V}'s truck?", "\"I'd run out of gas the evening before and had to get to work. I walked over to {V}'s truck, which I'd borrowed gas from before.\""), .direct("Why did you go so early?", "\"I start work at 6:30 and I had no gas. I didn't want to wake {V} up, so I thought I'd take a little and leave a note.\""), .direct("Where did you get the cans?", "\"They were mine, from my garage. I'd planned to fill them and bring them back to the car, and I'd have repaid {V} that weekend.\""), .direct("Had {V} said you could take gas?", "\"Two weeks ago {V} told me, take what you need if you ever run short. I took that as a standing invitation, and I should have knocked first.\""), .direct("What did you tell the deputy?", "\"The truth. I said I had run out of gas and was borrowing some, and I told the deputy {V} had let me do it once.\""), .direct("Why were two other cans in your car?", "\"I filled one earlier and was going to refill the others on the same trip. I wasn't hiding them. They were in plain view in the back seat.\""), .cross("You took about twenty gallons, didn't you?", "\"If that's what the cans and the tank add up to, then yes. It was more than I meant to take, and I wasn't counting.\""), .cross("You made three trips to the truck before dawn?", "\"I did, with the cans, because I couldn't carry it all at once. A camera across the street shows it, and I won't deny it.\""), .cross("You never asked {V} that morning?", "\"No, it was five in the morning and dark. I thought I'd settle up afterwards, and I see now that I should have asked first.\""), .cross("Did you leave a note?", "\"I meant to, but I hadn't gotten to it when {V} came out. I had the pen in my pocket, I'll admit I hadn't written anything.\""), .cross("You know {V} wanted to be asked?", "\"I do now. {V} said so in plain words to the deputy, and I understand it was wrong to rely on something said two weeks before.\"")],
        openings: ("Before dawn, {V} walked outside and found {D} crouched at the truck with a hose in the tank and a five-gallon can. Two more full cans were in {D}'s car, and {V} had never agreed to lend any gas that morning.", "{D} had run out of gas, needed to get to work, and had been told by {V} two weeks earlier to take what was needed. The defense says this was a neighbor's borrowing, made openly and with an honest belief in permission."),
        closings: ("Three trips to the truck in the dark, a hose in the tank, and twenty gallons gone. {D} had every chance to knock on {V}'s door, and a standing offer from two weeks earlier does not cover five in the morning.", "A neighbor heard {V} say take what you need, {D} stayed at the truck and answered every question, and there is no secret about what was done. Taking gas with a claim of right is not the intent to steal the State must prove."),
        timeline: [(0, "5:00 a.m.: {DL} at the truck."), (0, "5:40 a.m.: {V} comes outside."), (0, "6 a.m.: deputies arrive.")],
        identified: "{V} found {D} at the truck.",
        genders: ["D": .male])

    static let tireSlash = SmallCases.make(
        key: "story.tireSlash",
        category: .property,
        headlines: ["All Four Tires Slashed After Breakup", "Man Charged With Damaging Ex's Car"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a car, by slashing four tires, causing damage of $640, on {DATE}.",
        ages: 21...52,
        victim: true,
        summary: "{V} came out on {DATE} to find all four tires on {V.his} car slashed. A neighbor's camera showed a man in a gray jacket walk along the car at 2:10 a.m. {V} had ended a relationship with {D} the week before. {DL} says {D.he} was asleep and that gray jackets are common.",
        state: [E(.video, 3, "Neighbor's Camera", "A man in a gray jacket crouches at each tire in turn; his face is hidden."), E(.document, 2, "Tire Estimate", "Four tires and labor, $640.")],
        defense: [E(.statement, 1, "Alibi", "{DL}'s roommate says {D.he} came home at midnight and slept.")],
        role: "Sheriff's deputy",
        exam: [.direct("What does the neighbor's camera video show?", "\"At about 2:10 in the morning, a person in a gray jacket walks along {V}'s car and crouches at each of the four tires in turn. The face is hidden.\""), .direct("Why did you look at {D} as a possible suspect?", "\"{V} had ended a relationship with {D} just a week before, and {V} told me {DL} had been upset and had contacted {V.him} several times since.\""), .direct("What damage did you document?", "\"All four tires were slashed through the sidewall. The tire shop estimate for four tires and labor came to $640.\""), .direct("When did {V} report the damage, and what did you see?", "\"{V} called in the morning. All four tires were cut through the sidewall at the same height, and the cuts were clean enough to suggest a sharp blade, not a puncture.\""), .direct("How did the neighbor's video reach you?", "\"The neighbor offered it when I asked about cameras on the street. It covers the front of the car and the sidewalk, and the time stamp reads about 2:10 a.m.\""), .direct("What did the person on the video do?", "\"The person walked up along the car, crouched at each tire in turn, and left in the direction of the next block. The whole thing took under two minutes.\""), .cross("You can't see the face on that video, can you?", "\"No, the person's face is covered by a hood and the angle is poor. I can describe the jacket and the build, nothing more.\""), .cross("Isn't a gray jacket a pretty common item of clothing?", "\"It is, and I don't dispute that. It's one fact that fits, not the only one, and I treat it as part of the whole picture.\""), .cross("The roommate told you the defendant was home. Why did you discount that?", "\"The roommate said {D.he} came in around midnight and went to sleep. The roommate was asleep too, so cannot say who left or came back after that.\""), .cross("Did you recover a knife from {D} or from {D}'s home?", "\"No. We did not search for one and nothing was found that I could connect to the damage.\""), .cross("Did the video show the person's build or the way they walked clearly enough to compare with the defendant?", "\"Not clearly. The video is grainy and at night, and I would not tell this jury it identifies {DL} by build.\"")],
        theory: ("{D} slashed four tires after a breakup.", "A gray jacket on grainy video and a sleeping alibi."),
        allocution: "\"I was angry. I'll pay for the tires.\"",
        truths: ("{DL}'s gray jacket had a rubber smear on the sleeve that matched the tire sidewall.", "{V}'s own cousin, who had a grudge, owned the same jacket."),
        defendant: [.direct("Where were you at 2 a.m. the night the tires were slashed?", "\"I was at home, in bed. I came in around midnight and went to sleep. I did not go near {V}'s street.\""), .direct("Do you own a gray jacket?", "\"Yes, I own one, but so does about everybody I know. It is a plain gray hoodie I wear all the time.\""), .direct("How did you feel about the breakup?", "\"I was hurt and I was sad. I was not violent about it. I would never do something like slash someone's tires.\""), .direct("What time did you get home that night?", "\"About midnight. I walked in, said goodnight to my roommate, and went to bed. I had work the next morning.\""), .direct("Did you leave the apartment again that night?", "\"No. I was asleep by about half past twelve, and I did not wake up until my alarm.\""), .direct("Why did you tell the deputy you owned a gray jacket?", "\"Because I do, and I figured the deputy would find out. It's a plain jacket I bought at a chain store, and I know three other people who have the same one.\""), .cross("You and {V} had just broken up, and you were angry, weren't you?", "\"I was hurt. Angry, maybe, a little. But there is a big difference between being upset and going out in the night with a knife.\""), .cross("Nobody can confirm you were in the apartment at 2 a.m., can they?", "\"My roommate was asleep, so no, nobody can see me in bed. I wish I had something better to offer you than that.\""), .cross("The person on the video moves like someone who knows the car. You knew it, didn't you?", "\"Of course I knew {V}'s car. I had ridden in it for months. That does not mean I was the one on that video.\""), .cross("You and {V} had broken up a week earlier. You were upset, weren't you?", "\"I was hurt, yes. I didn't like how it ended, but being sad is not the same as slashing anyone's tires.\""), .cross("The person on the video went to each tire in turn, like someone who knew exactly where the car would be parked. Who knew that?", "\"Lots of people. {V} parks on that street every night, and anyone who has ever visited {V.him} would know.\"")],
        openings: ("Four tires, slashed one by one, at 2:10 in the morning, one week after {V} ended a relationship with {D}. A neighbor's camera caught a gray-jacketed figure at the car, and the State will connect the dots.", "The State has a grainy video of a person in a gray jacket and a recent breakup. The defense will show that this is a common jacket, no face is visible, and {D} was home asleep."),
        closings: ("Look at the timing: a breakup on Monday, four slashed tires the following week, and a gray jacket that fits. The motive is real and the person on that video knew exactly which car to find.", "Nobody can see a face on that video. A gray jacket is something half the county owns, and a breakup is not proof of a crime. The State has asked you to fill in what the evidence leaves out."),
        timeline: [(-7, "{V} ends the relationship."), (0, "2:10 a.m.: a man slashes four tires."), (0, "Morning: {V} reports the damage.")],
        identified: "{V}'s guess and a neighbor's camera.",
        genders: ["D": .male])

    static let tailgateShove = SmallCases.make(
        key: "story.tailgateShove",
        category: .violent,
        headlines: ["Football Tailgate Argument Ends in a Shove", "Man Charged After Parking Lot Pushing Match"],
        law: "simpleAssault",
        spec: "Assaulted {V} by shoving {V.him} with both hands, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "At a high school football tailgate on {DATE}, {D} and {V} argued about a folding table that blocked a parking space. According to {V}, {D} shoved {V.him} hard enough to knock {V.him} into a cooler. {D} says {V} had been drinking and stepped into {D.his} chest. A parent filmed the end.",
        state: [E(.video, 2, "Parent's Video", "The last seconds show {D}'s hands on {V}'s chest and {V} falling into a cooler."), E(.document, 1, "Urgent Care Note", "A bruised hip and a sprained wrist.")],
        defense: [E(.statement, 2, "Other Parent", "Another parent says {V} stepped chest-to-chest with {D} first.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see when you arrived at the tailgate?", "\"I found two adults who had been arguing over a folding table blocking a parking space. {V} was on the ground near a cooler, complaining of hip and wrist pain.\""), .direct("What does the parent's video show?", "\"The last few seconds show {D}'s hands on {V}'s chest, then {V} falling backward into a cooler. It does not show the beginning of the argument.\""), .direct("What injuries were documented?", "\"The urgent care note lists a bruised hip and a sprained wrist, consistent with falling hard against a cooler.\""), .direct("Who called deputies, and what did the caller say?", "\"A parent called and said two adults had gotten into a physical argument over a table and one had fallen into a cooler. I arrived about ten minutes later.\""), .direct("What did {V} tell you when you spoke with {V.him}?", "\"{V} said {DL} had shoved {V.him} hard in the chest over the table and that {V.he} had fallen into a cooler. {V} was holding a wrist when I arrived.\""), .direct("What did {D} tell you?", "\"{DL} said {V} had been drinking and stepped into {D.his} chest, and that {D.he} pushed {V.him} away to get some space. {DL} did not deny that the push happened.\""), .cross("The video doesn't show who started it, does it?", "\"No. It starts right as the shove happens, so I cannot tell you from the video who stepped toward whom first.\""), .cross("Isn't it true both of them had been drinking?", "\"Yes. Both smelled of alcohol and both admitted having beer. I note that for both sides.\""), .cross("Another parent said {V} stepped chest-to-chest with the defendant. Did you hear that?", "\"I did. One parent described it that way. Another parent described it differently, so I recorded both accounts in my report.\""), .cross("Was the folding table actually blocking a parking space?", "\"It was partly in the space, yes. Both of them agreed on that, though they disagreed about who put it there.\""), .cross("Did you speak to the parent who filmed the end of the video?", "\"Yes. That parent said the filming started when voices got louder and did not see how it began, only the push and the fall.\"")],
        theory: ("{D} shoved a man over a parking space at a football game.", "Two men chest to chest and a push that came second."),
        allocution: "\"I shouldn't have put my hands on {V.him}. I'm sorry.\"",
        truths: ("A parent heard {DL} say, 'move the table or I'll move you.'", "A parent heard {V} say, 'go ahead and try it,' before the shove."),
        defendant: [.direct("How did the argument over the table begin?", "\"A folding table was blocking a parking space I wanted. I asked the owner to move it, and {V} came at me and the conversation got heated fast.\""), .direct("What did {V} do right before the shove?", "\"{V} stepped right up into my chest, nose to nose, and kept coming forward. I felt like I had nowhere to go.\""), .direct("What did you do?", "\"I put my hands up and pushed {V.him} back to get some space. I did not mean to send {V.him} into the cooler. I did not plan any of it.\""), .direct("What did you do when {V} stepped up to you?", "\"I told {V.him} to back up. {V.He} didn't, so I put my hands on {V.his} chest to create some distance.\""), .direct("How much had you had to drink at the tailgate?", "\"A few beers over a couple of hours. I wasn't drunk, but I wasn't completely sober either, and I'm not going to pretend otherwise.\""), .direct("What did you think when you saw {V} fall into the cooler?", "\"I felt awful. I reached out to help, but by then people were crowding in and a parent was already calling deputies.\""), .cross("You pushed {V} hard enough to knock {V.him} over, didn't you?", "\"I pushed to get {V.him} off me. I did not expect {V.him} to fall. I'm sorry {V.he} was hurt, but it was one push.\""), .cross("You could have walked away from a parking space argument, couldn't you?", "\"Yes. I could have, and I should have. I lost my temper for a few seconds, and I wish I had just left.\""), .cross("You said you only wanted distance. But the video shows both of your hands on {V}'s chest, doesn't it?", "\"It does. It happened fast, and I used both hands because {V.he} was close. I did not intend to put {V.him} on the ground.\""), .cross("A parent heard you say 'move the table or I'll move you.' Did you say that?", "\"I may have said something like it. People say things in an argument, and I never meant it as a promise to hurt anyone.\""), .cross("Another parent says {V} stepped up to you first. Did you ever put your hands on {V} before that?", "\"I did not touch {V} before the shove. Once {V} was close enough to bump me, I pushed, and I did it harder than I meant to.\"")],
        openings: ("Over a folding table and a parking space, {D} put both hands on {V}'s chest and shoved {V.him} into a cooler. A parent's video captured the end, and an urgent care note records the injuries.", "Two people were chest to chest at a tailgate, both had been drinking, and the push came after {V} stepped into {D}. The defense will show a short, defensive shove, not an assault."),
        closings: ("The video shows the shove. The urgent care note shows a bruised hip and sprained wrist. Whatever words came first, putting your hands on someone and driving them into a cooler is an assault.", "{V} stepped into {D}'s chest first, and another parent saw it. What followed was a quick push to make room, not an attack. The State cannot show the beginning, and the beginning matters."),
        timeline: [(0, "Friday evening: the dispute over the table."), (0, "The shove."), (0, "A parent calls deputies.")],
        identified: "A parent's video.",
        genders: ["D": .male])

    static let falseNameDeputy = SmallCases.make(
        key: "story.falseNameDeputy",
        category: .publicOrder,
        headlines: ["Driver Gave His Brother's Name at Traffic Stop", "Obstruction Charge After False Identity"],
        law: "obstruction",
        spec: "Willfully and unlawfully delayed and obstructed a public officer by giving a false name during a lawful stop, on {DATE}.",
        ages: 19...50,
        victim: false,
        summary: "A deputy stopped {D} for speeding on {DATE}. {D} had no license on {D.him} and gave the name of {D.his} brother, with the brother's date of birth. The deputy wrote a citation in that name. The brother's license was clean, and a fingerprint check at the jail revealed {D}'s true identity. {DL} says {D.he} panicked because of an unpaid fine.",
        state: [E(.video, 3, "Body Camera", "{D} gives a name and date of birth; the citation is written in the brother's name."), E(.document, 2, "Jail Fingerprint Record", "The prints belong to {D}, who has an unpaid fine.")],
        defense: [E(.statement, 1, "Panic", "{DL} says {D.he} was afraid of jail over the fine.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop {D}?", "\"I clocked {D} speeding on the county highway and made a traffic stop on {DATE} in the afternoon. {DL} was driving and was the only person in the car.\""), .direct("What did the defendant give you for identification?", "\"No license. {D.He} gave me a name and a date of birth verbally, and I wrote a citation based on what I was told.\""), .direct("Did you check that name?", "\"I ran it through dispatch and it returned a driver with a clean record. The photo on file didn't pull up on my screen right then, which is common.\""), .direct("How was the false name discovered?", "\"At the jail, a fingerprint check showed the prints belonged to {D.him}, who had an unpaid fine. That revealed {D.his} true identity.\""), .direct("What does your body camera show about the name?", "\"It shows {DL} stating a name and date of birth clearly, without hesitation. It also shows me reading the citation back to {DL} before {DL} signed.\""), .direct("What did the defendant do when confronted at the jail?", "\"{D.He} admitted giving a sibling's name, said {D.he} had panicked over the unpaid fine and was afraid of being taken to jail.\""), .cross("Isn't it true the defendant gave the name of a real relative, not a made-up one?", "\"Yes, it was a sibling's actual name and date of birth. That's why the record came back clean, which is also why it nearly worked.\""), .cross("Did the sibling's license suffer from this citation?", "\"The citation was written under the sibling's name, but the court corrected the record once the true identity was known. I'm not aware of any lasting harm.\""), .cross("Did the defendant resist, run, or argue with you?", "\"No. {D.He} was calm, polite, and stayed in the car. {D.He} signed the citation and accepted it without any trouble.\""), .cross("Was the speed stop itself routine?", "\"It was an ordinary speeding stop, nothing unusual. I'm aware {DL} could have been arrested on the fine if I'd known the real name.\""), .cross("Did {D} correct the name before leaving the scene?", "\"No. {D.He} drove away after the citation, and the correction came only after the fingerprints at the jail.\"")],
        theory: ("{D} gave a false name to avoid being arrested on a fine.", "A panicked driver who gave a name he regretted."),
        allocution: "\"I panicked. I put my brother in a bad spot.\"",
        truths: ("{DL} had used his brother's name at two earlier stops.", "The brother had given {D} permission to use his name for emergencies."),
        defendant: [.direct("Why did you give the deputy a false name?", "\"I panicked. I had an unpaid fine and no license on me, and I was afraid I'd be taken to jail on the spot.\""), .direct("Whose name did you give?", "\"My sibling's. I knew the name and birth date by heart, and it came out before I'd thought about what I was doing.\""), .direct("How did your sibling feel about it?", "\"Upset at first, then understanding. My sibling told the court I'd been scared, and I felt terrible about putting that name on a ticket.\""), .direct("What was the unpaid fine for?", "\"An old traffic matter that I let slide while money was tight. I meant to take care of it, and I never got to the clerk's office.\""), .direct("How did you act at the jail?", "\"I told the truth once they had my fingerprints. There was no point denying it, and I admitted it was me and said I was sorry.\""), .direct("What have you done to fix things?", "\"I've paid the old fine, taken care of the new citation under my own name, and apologized to my sibling for dragging them into it.\""), .cross("You looked the deputy in the eye and gave a name that was not yours?", "\"Yes. I said it on camera and I knew while saying it that it wasn't true. I'm not going to dodge that.\""), .cross("You gave your sibling's date of birth too?", "\"Yes, the full date. I picked the whole identity so it would sound real, and that was a deliberate choice, not a slip of the tongue.\""), .cross("You've given your sibling's name at earlier stops, haven't you?", "\"I've used it before, in a couple of other situations. I knew it was wrong. That isn't something I'm proud of.\""), .cross("Did your sibling ever tell you that you could use the name?", "\"In an emergency, my sibling once said it was fine. I took that too far, and a traffic stop over a fine isn't what was meant.\""), .cross("You could have simply told the deputy you owed a fine?", "\"I could have. I was frightened, but I know now that the truth would have been a lot cheaper than what I did.\"")],
        openings: ("{D} was stopped for speeding with no license and gave the deputy a sibling's name and date of birth, and a citation was written in that name. Jail fingerprints exposed the lie, and the State will show a deliberate false statement to avoid arrest on an unpaid fine.", "{D} panicked over an old fine and said the first name that came to mind. The defense says the deputy lost no time, the sibling suffered no lasting harm, and {D} told the truth as soon as the prints were taken."),
        closings: ("The body camera shows a clear name and a clear date of birth given with no hesitation. A false identity given to a deputy to avoid a fine is no panic reflex but a choice, and {D} made it.", "{D} was alone, calm, and terrified of jail over an old fine, and admitted the truth the moment fingerprints were taken. A panicked lie that harmed nobody, and was corrected right away, falls short of what the State needs to prove."),
        timeline: [(0, "Afternoon: speeding stop."), (0, "{DL} gives the false name; a citation is written."), (0, "Fingerprints at the jail reveal {D}'s identity.")],
        identified: "Jail fingerprints.",
        genders: ["D": .male])

    static let scrapGutters = SmallCases.make(
        key: "story.scrapGutters",
        category: .property,
        headlines: ["Aluminum Gutters Stripped From Vacant House", "Scrap Yard Records Link Man to Gutter Theft"],
        law: "misdLarceny",
        spec: "Stole aluminum gutters and downspouts valued at $620 belonging to {V}, from a vacant house, on {DATE}.",
        ages: 20...58,
        victim: true,
        summary: "{V} owns a vacant rental house that was being renovated. Over a weekend on {DATE}, someone stripped all the aluminum gutters and downspouts. A scrap yard record shows {D} sold 70 pounds of aluminum gutters for $42 the next Monday. {DL} says {D.he} bought a load from a man at a flea market.",
        state: [E(.document, 3, "Scrap Yard Ticket", "{D}'s ID on a ticket for 70 pounds of aluminum gutters, the Monday after the theft."), E(.physical, 2, "Photos", "The house's bare fascia with gutter brackets still on the wall.")],
        defense: [E(.statement, 1, "Flea Market", "{DL} says {D.he} bought the scrap for $15 and flipped it.")],
        role: "Scrap yard clerk",
        exam: [.direct("What do you do at the scrap yard?", "\"I work the scale and the counter at the scrap yard. I weigh what comes in, check identification, and fill out a ticket for every sale.\""), .direct("What did {D} bring to you on that Monday?", "\"{D} brought in seventy pounds of aluminum gutters and downspouts and showed an ID. I weighed them and paid $42, and the ticket carries {D.his} name.\""), .direct("How did the gutters look when you took them in?", "\"They were cut and bent in lengths, and some still had pieces of bracket attached. That is typical for gutters that have been pulled off a house.\""), .direct("What do the tickets for aluminum sales usually record?", "\"The seller's name from an ID, the date, the material, and the weight. {D.his} ticket shows seventy pounds of aluminum gutters for forty-two dollars.\""), .direct("How do you check what is brought in?", "\"I look at the load, weigh it, and make sure nothing is hazardous. For gutters I check for painted pieces, because those pay less.\""), .direct("How did the gutters the defendant brought in compare with what is usually sold?", "\"They were fresh cuts in long sections with a few bent elbows, and some still had a bracket attached. It looked like a house load, not a mixed pile.\""), .cross("People sell scrap to your yard every day, don't they?", "\"All day long. Most of them are contractors, flippers, and folks cleaning out a garage. Selling scrap is perfectly legal.\""), .cross("{D} used a real ID. Does that tell you anything?", "\"It tells me {DL} was not hiding. Someone selling stolen scrap might think twice about using a real name, but I cannot say what was in {D.his} mind.\""), .cross("Did the defendant say where the gutters came from?", "\"I do not ask that for every ticket. I recall {DL} saying something about getting a load from someone, but I can't repeat it word for word.\""), .cross("How many people sold aluminum gutters at your yard that week?", "\"Several. Gutters come in all the time from contractors and renovation crews, and I would not be able to name each seller from memory.\""), .cross("Does your yard ask sellers to prove where scrap came from?", "\"Not routinely. We take a photo ID, which {D.he} gave, and we keep the ticket on file in case a sheriff's office comes asking later.\"")],
        theory: ("{D} sold gutters stripped from a vacant house.", "A scrap flipper who bought a load cheap."),
        allocution: "\"I should have asked more. I'll pay for the damage.\"",
        truths: ("{DL}'s truck was seen at the house on Saturday.", "A man arrested for scrap theft said he sold the gutters to {DL}."),
        defendant: [.direct("Where did you get the gutters you sold?", "\"I bought a load of scrap from a seller at a flea market for about fifteen dollars. I figured I could flip it at the scrap yard for a few dollars profit.\""), .direct("Did you take them off a house?", "\"No. I have never touched that vacant rental. I bought them already pulled down, in a pile, and loaded them in my truck.\""), .direct("Why did you use your real ID at the yard?", "\"Because I felt I had no reason to hide anything. I thought I was making an honest few dollars on something I paid for.\""), .direct("What can you tell us about the flea market?", "\"It was on a Sunday morning. A seller had a pile of aluminum in the bed of a pickup, said it was left over from a job, and offered the whole load for fifteen dollars.\""), .direct("What did you do with the scrap after you bought it?", "\"I put it in my truck and took it to the scrap yard the next day. I figured I'd make a little money.\""), .direct("Do you do this kind of buying and selling often?", "\"Now and then. I look for deals at flea markets and sell what I can, mostly metal, sometimes tools.\""), .cross("The gutters still had bracket pieces and bends from being cut off a wall. You noticed that?", "\"I saw they were bent, but a lot of scrap is. I did not think about where they came from, and I should have asked more.\""), .cross("You can't give us the name of the seller who sold them to you, can you?", "\"No. It was a cash deal at a flea market. I did not get a name, and I know that sounds convenient.\""), .cross("Fifteen dollars for seventy pounds of aluminum. Didn't that seem too cheap?", "\"It seemed like a deal. I'll admit I did not question it, because a good price is why I bought it.\""), .cross("You never asked the seller where the gutters came from?", "\"I asked if they were clean, and the seller said yes. I didn't ask where they came from, and I know that was careless.\""), .cross("The gutters had bracket pieces still attached. Doesn't that tell you they came off a house?", "\"It tells me they came from some house, yes. I assumed it was a renovation job like the seller said, not a theft.\"")],
        openings: ("Over one weekend, a vacant rental house lost every gutter and downspout. On Monday, {D} sold seventy pounds of aluminum gutters at a scrap yard and signed a ticket with an ID.", "{D} is a scrap flipper who bought a load of aluminum cheaply at a flea market and sold it for a small profit. The defense will show an honest transaction, done under {D.his} own name."),
        closings: ("The weekend the gutters vanished, the gutters were cut and bent when {D} sold seventy pounds the following Monday. That ticket carries {D.his} name, and no flea market seller has ever been produced.", "Selling scrap under your own name is not how a thief behaves. {D} bought a load cheap and sold it for a few dollars. The State has a ticket, not proof that {D.he} took anything from that house."),
        timeline: [(0, "Weekend: the gutters disappear."), (2, "Monday: {DL} sells the scrap."), (5, "{V} finds the bare fascia.")],
        identified: "The scrap yard's ticket.",
        genders: ["D": .male])

    static let campusLaptop = SmallCases.make(
        key: "story.campusLaptop",
        category: .property,
        headlines: ["Laptop Taken From Library Table Found at Pawn Shop", "Student Says Man Walked Off With Her Laptop"],
        law: "possStolen",
        spec: "Possessed a laptop computer valued at $780 belonging to {V}, knowing and having reasonable grounds to believe it stolen, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V}, a student, stepped away from a library table on {DATE} for five minutes and returned to find {V.his} laptop gone. Two days later the laptop was pawned by {D} at a pawn shop. {V}'s serial number matched. {DL} says {D.he} bought the laptop for $100 from a man in the parking lot.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on a ticket for the laptop; serial number matches {V}'s receipt."), E(.video, 2, "Library Camera", "A man in a cap takes a laptop from an unattended table.")],
        defense: [E(.statement, 1, "Parking Lot Sale", "{DL} says {D.he} bought the laptop from a stranger for $100.")],
        role: "Pawn shop clerk",
        exam: [.direct("What is your role at the pawn shop?", "\"I work the counter, buy and appraise merchandise, and keep our transaction records. Electronics come through daily, and we log serial numbers for every item we buy.\""), .direct("What happened when {D} came in?", "\"Two days after the laptop disappeared from a library table, {D} came in with it and asked for a loan. I logged {D.his} ID, issued a pawn ticket, and recorded the serial number.\""), .direct("What did the serial number check show?", "\"The next morning our serial check flagged it against a report from a student at the college. The serial matched {V}'s purchase receipt exactly.\""), .direct("What did the defendant tell you when pawning it?", "\"{D.He} said the laptop was a personal one, that {D.he} had no further use for it, and asked for a hundred dollars. {D.He} didn't seem nervous.\""), .direct("What condition was the laptop in?", "\"It was clean and had a sticker on the lid that looked like a student's. The sticker was still on when {V} identified it, and the charger came in with it.\""), .direct("What did you do once it was flagged?", "\"I contacted the sheriff's office with the ticket and {D.his} ID. The deputy took the laptop and returned it to {V}.\""), .cross("Isn't it true the defendant used a real ID with a real address?", "\"Yes. {DL} handed over a valid driver's license and the ticket carries {DL}'s true name and address, so it was easy to trace.\""), .cross("Did the defendant ask any questions you remember about the value or its origin?", "\"No, nothing unusual. I don't recall {D.he} asking about anything except how much cash I'd give.\""), .cross("How many items do you take in on a typical day that later get flagged?", "\"Only a few a year. Most people who pawn items are honest, and I treat {DL}'s visit as an ordinary transaction until the flag.\""), .cross("Did the defendant resist or try to leave when you took the laptop?", "\"I wasn't in the room when it was collected. I know {D.he} was not present then and nobody told me of any argument.\""), .cross("Do you know where {D} got the laptop?", "\"No. I only know what the pawn ticket shows. {D.He} said it was personal, but I have no idea whether that's true.\"")],
        theory: ("{D} pawned a stolen laptop two days after it was taken.", "A buyer who didn't know the laptop was stolen."),
        allocution: "\"It was too cheap. I should have asked questions.\"",
        truths: ("The man in the library video wore the same cap found in {DL}'s car.", "The man who sold the laptop was arrested later and named {DL} as a buyer."),
        defendant: [.direct("Where did you get the laptop?", "\"I bought it for $100 from a stranger in a parking lot. The seller said it was a spare and that the price was a bargain.\""), .direct("Why did you buy it from a stranger?", "\"Mine had died and I needed one for work. The price was low, and I didn't ask questions I should have, because I wanted a deal.\""), .direct("Why did you pawn it two days later?", "\"It wouldn't hold a charge and the screen kept flickering. I figured I'd get my money back at the pawn shop and be done with it.\""), .direct("Did you think it might be stolen?", "\"Not in the moment. A hundred dollars for a laptop in good shape should have made me suspicious, but I convinced myself it was fine.\""), .direct("Did you use your real ID at the pawn shop?", "\"Of course. I'd have no reason to hide my name if I thought I did nothing wrong, and I gave my own license without a second thought.\""), .direct("What did you tell the deputy?", "\"Everything I've told you. I described the stranger and the parking lot, and I gave the deputy my phone number.\""), .cross("You didn't get a receipt from the seller?", "\"No. It was a cash handoff with no paper. I can't point to anything that shows I paid or who I paid.\""), .cross("Can you give a name for the seller?", "\"No. I never asked for a name, and I wouldn't know the person's face if I saw it again. That's a hard fact for me to admit.\""), .cross("You pawned it within two days of buying it?", "\"Yes. I pawned it fast because it wasn't working right and I wanted my money back before I lost more.\""), .cross("You own a cap like the one in the library video, don't you?", "\"I own a few caps, and I'm told one found in my car resembles it. A common cap doesn't make me the person in that video.\""), .cross("Is it a coincidence the laptop you bought was taken from a library table?", "\"I understand how that sounds. I can only say I didn't take it and had no idea where it came from.\"")],
        openings: ("{V} stepped away from a library table for five minutes and came back to an empty spot. Two days later {D} pawned that same laptop for cash, and the serial number on the pawn ticket matches {V}'s receipt.", "{D} bought a used laptop for $100 in a parking lot, used a real ID to pawn it, and never knew it had been stolen. The defense says handling stolen goods requires knowledge, and {D} had none."),
        closings: ("The serial number matches, the ticket carries {D}'s name, and the sale came just two days after the theft. A $100 laptop from a stranger in a parking lot is the kind of deal that should have raised a question, and {D} never asked it.", "{D} gave a real name and address to the pawn shop, an act no one aware of a theft would do. The State must show {D} knew the laptop was stolen, and buying cheaply from a stranger is poor judgment, not proof of guilt."),
        timeline: [(0, "Afternoon: the laptop is taken."), (2, "{DL} pawns it."), (3, "The pawn shop's serial check flags it.")],
        identified: "The pawn shop's serial check.",
        genders: ["D": .male, "V": .female])

    static let returnFraud = SmallCases.make(
        key: "story.returnFraud",
        category: .whiteCollar,
        headlines: ["Woman Returned Stolen Goods for Store Credit", "Receipt Check Ends Return Scheme"],
        law: "falsePretenses",
        spec: "Obtained $284 in store credit from a retail store by falsely representing that merchandise had been purchased, on {DATE}.",
        ages: 24...60,
        victim: false,
        summary: "A department store's return desk gave {D} $284 in store credit on {DATE} for a coat and two sweaters with a receipt. A loss prevention officer noticed the receipt numbers matched a receipt from an earlier purchase of different items. The coat and sweaters still had security tags from the sales floor. {DL} says a friend gave {D.him} the merchandise and receipt as a gift.",
        state: [E(.document, 3, "Receipts", "The return receipt matches a purchase of different items three weeks earlier."), E(.physical, 2, "Security Tags", "The coat and sweaters still had sales-floor tags.")],
        defense: [E(.statement, 1, "A Gift", "{DL} says a friend gave {D.him} the items and the receipt.")],
        role: "Department store loss prevention manager",
        exam: [.direct("What made you look closer at that return?", "\"The receipt number matched a purchase from three weeks earlier, and that purchase was for different items. The coat and two sweaters on the counter did not match it.\""), .direct("What did you notice about the merchandise itself?", "\"The coat and both sweaters still had the sales-floor security tags attached. Merchandise that was actually bought and carried out has had those tags removed at the register.\""), .direct("How much credit did the return desk issue?", "\"The desk issued $284 in store credit before I got to it. I stopped any further transaction and called deputies after reviewing both receipts.\""), .direct("How does your department catch receipt problems?", "\"We look at receipt numbers and compare them to the original sale in our system. When a return comes up with a receipt already tied to different items, the register flags it.\""), .direct("What items were on the original purchase?", "\"A set of kitchen items, not clothing. The receipt for that sale was from three weeks earlier and did not list a coat or sweaters.\""), .direct("What did you do when you saw the flag?", "\"I went to the return desk and asked {D} to step aside. I looked at the tags and the receipt, then asked where the clothes came from.\""), .cross("{D} told you a friend gave over the items and the receipt, didn't {D.he}?", "\"Yes, that was {D.his} explanation. I had no way of confirming it at the time, and I did not interview the friend.\""), .cross("{D} didn't argue or run when you stepped in, did {D.he}?", "\"No. {D.He} stayed at the desk, answered my questions, and did not resist. I have no complaint about how {D.he} behaved once we spoke.\""), .cross("Isn't it possible someone else bought the items and handed over the wrong receipt by mistake?", "\"It's possible a receipt could be mixed up, but the tags are what bother me. A real purchase does not leave security tags on the clothing.\""), .cross("Could the receipt have been copied rather than handed over?", "\"It's possible, but that would not change what we found, which is that the receipt belonged to a different purchase.\""), .cross("Did {D} try to leave when you approached?", "\"No. {D.He} stayed at the desk the whole time and answered every question I asked.\"")],
        theory: ("{D} returned stolen merchandise with someone else's receipt for credit.", "A gift recipient who trusted a friend's paperwork."),
        allocution: "\"I should have checked the receipt. I'm sorry.\"",
        truths: ("{DL}'s phone held a photo of the receipt sent by {D.his} friend with 'make it work.'", "The friend, who worked at the store, gave {DL} the items to return and kept the credit card."),
        defendant: [.direct("How did you come to have the coat and sweaters?", "\"A friend gave me the coat and the two sweaters along with a receipt, and said I could return them for credit if they did not fit.\""), .direct("Did you believe the paperwork was in order?", "\"Yes. I had no reason to doubt it. I figured a friend would not hand me a bad receipt, and I took it to the return desk like any customer.\""), .direct("What did you do when the manager stopped you?", "\"I stayed calm and told the manager what I had been told. I did not walk away or argue, because I did not think I had done anything wrong.\""), .direct("Describe the friend who gave you the clothes for the jury.", "\"A friend I've known for years told me {D.he} couldn't use a coat and two sweaters and asked me to return them for credit. I thought it was generous.\""), .direct("What did your friend give you besides the clothes?", "\"A paper receipt in a bag. I put the bag in my car and took it to the store a few days later.\""), .direct("How did you feel when the loss prevention manager spoke to you?", "\"Confused first, then scared. I told the manager exactly where I got everything, and I offered to call my friend right there.\""), .cross("The tags were still on every item, weren't they?", "\"They were. I didn't look at the clothes closely before I carried them in. I know now that should have told me something.\""), .cross("You accepted $284 in store credit for items you did not buy, correct?", "\"I accepted what the desk gave me, believing the items were a gift that I was entitled to return. I never paid for them myself, that's true.\""), .cross("The receipt matched a different purchase. Did you read it before you handed it over?", "\"I glanced at it, but I did not compare the item list line by line. I trusted my friend, and that was a mistake on my part.\""), .cross("The tags were still on every item. Didn't that tell you the clothes had never been worn or bought?", "\"It did occur to me later. At the time I thought it meant my friend never wore them, which is what I was told.\""), .cross("You accepted $284 in credit. Didn't you ask why a friend wouldn't return them personally?", "\"I did ask, and the answer was that the friend was busy. I should have been more careful about taking something I couldn't verify.\"")],
        openings: ("A department store return desk issued $284 in credit for a coat and two sweaters. The State will show that the receipt belonged to a different purchase and that the sales-floor tags were still on the clothes.", "{D} was handed clothes and a receipt by a friend and took them to a return desk like any customer. The defense will show someone who trusted paperwork that turned out to be wrong, and who never ran or hid."),
        closings: ("Different items on the receipt, security tags still attached, and $284 in credit. Those facts do not fit an honest return, and a person who carries tagged clothes to a desk should have known something was off.", "{D} did not hide, argue, or run. A trusted friend supplied the clothes and the receipt, and {D} acted on that. The State cannot prove {D} knew the paperwork was false."),
        timeline: [(-21, "The original purchase on the receipt."), (0, "{DL} returns the items for credit."), (0, "Loss prevention stops {DL} at the desk.")],
        identified: "The loss prevention officer's receipt check.",
        mood: .sympathetic,
        genders: ["D": .female])

    static let fakeLicense = SmallCases.make(
        key: "story.fakeLicense",
        category: .whiteCollar,
        headlines: ["Underage Man Used Fake License to Buy Beer", "Clerk Spots Fake Driver's License at Gas Station"],
        law: "forgery",
        spec: "Possessed a forged driver's license with intent to utter it, on {DATE}.",
        ages: 18...22,
        victim: false,
        summary: "A gas station clerk scanned {D}'s driver's license on {DATE} while selling a twelve-pack, and the scanner flagged it. The license listed {D} as 24 and carried another man's name. {D} is 19. A deputy found a second fake license in {D}'s wallet. {DL} says {D.he} bought the licenses online as novelty items.",
        state: [E(.physical, 3, "The Licenses", "Two forged licenses with {D}'s photo and different names and birthdates.", .search), E(.video, 2, "Store Camera", "{D} hands the clerk a license and receives a twelve-pack.")],
        defense: [E(.statement, 1, "Novelty", "{DL} says the licenses came from a website selling novelty IDs.")],
        role: "Gas station clerk",
        exam: [.direct("What were you doing at the gas station that day?", "\"I was working the register on {DATE}. {D} came up with a twelve-pack of beer and handed me a driver's license to buy it.\""), .direct("What do you do when someone hands you a license for alcohol?", "\"I look at the photo and the birth date, and then I scan the barcode into the register. If the scanner doesn't accept it, I stop the sale.\""), .direct("What happened when you scanned {D}'s license?", "\"The scanner beeped red and flagged it. The card said the holder was 24, but the barcode didn't match the printed name, and it carried a different name than the face.\""), .direct("What did you do then?", "\"I told {DL} I couldn't sell the beer and kept the license at the counter. I called the sheriff's office while {DL} stood there looking uncomfortable.\""), .direct("What did the deputy find?", "\"The deputy searched {DL}'s wallet with consent and found a second license, also with {DL}'s photo and a different name and birth date.\""), .direct("Did the store camera capture the sale attempt?", "\"Yes. It shows {DL} handing me the license and me setting the twelve-pack on the counter. It also shows me holding the card after the scan.\""), .cross("Isn't it true you did not sell the beer?", "\"Correct. I didn't ring it up and no alcohol left the store. The twelve-pack stayed on the counter.\""), .cross("Does the license look obviously fake?", "\"Not at first glance. The photo is a decent match and the card feels real. I only knew because the scanner rejected it.\""), .cross("Did the defendant argue or try to run?", "\"No. {DL} said it was just a novelty and asked for it back, but stayed until the deputy arrived.\""), .cross("Did the defendant say anything about where the license came from?", "\"Only that it was a joke and came from a website. I didn't ask more, and I wouldn't know whether that was accurate.\""), .cross("Have you seen scanner failures on real licenses?", "\"Rarely. Sometimes a worn card won't scan, but this one was flagged as not matching the barcode, which isn't the same as a smudge.\"")],
        theory: ("{D} used a forged license to buy beer.", "A teenager with a novelty ID and a bad idea."),
        allocution: "\"It was stupid. I won't do it again.\"",
        truths: ("{DL}'s browser history showed a search for 'IDs that scan.'", "The website's page said 'for novelty use only' in small print."),
        defendant: [.direct("How old are you, and what was the license?", "\"I'm 19. The license I handed over said I was 24, with a different name, and I bought it online as a novelty ID.\""), .direct("Where did you buy them?", "\"From a website that sells novelty cards. The page said for novelty use only in small print, and I ordered two about two weeks before.\""), .direct("Why did you take one to the gas station?", "\"I wanted beer for a party that weekend and thought I might get away with it. It was a dumb idea and I knew it as soon as I handed it over.\""), .direct("What did you do when the scanner flagged it?", "\"I told the clerk it was just a novelty, asked for it back, and stayed put. I didn't try to leave or run.\""), .direct("Did you cooperate with the deputy?", "\"Yes. I let the deputy look in my wallet, and I told the truth about the second card and where it came from.\""), .direct("How has this affected you?", "\"Embarrassed. I've thrown both away, and I wouldn't do it again. It seemed like a harmless joke until I saw a deputy walk in.\""), .cross("You searched for IDs that scan before ordering, didn't you?", "\"I did look for ones that would work. That's what I wanted, and I won't pretend I was searching for a gag gift.\""), .cross("You knew the name on the license wasn't yours?", "\"Of course I did. It was a made-up name, and I put my own picture on it. There's no confusion about whose name was on it.\""), .cross("The card said you were 24 when you are 19?", "\"Yes. I chose a birth date that would make me old enough, because I was trying to buy beer, plain and simple.\""), .cross("You had a second license in your wallet?", "\"I did. I ordered two, and I'd planned to use whichever one worked. That is why the deputy found a second card.\""), .cross("The fine print says novelty only, but you used it as real?", "\"Yes, I used it at a register, which is exactly what the page says not to do. I read the print and ignored it.\"")],
        openings: ("A teenager walked into a gas station on {DATE}, handed over a license that said 24 with another name on it, and asked for a twelve-pack. The clerk's scanner flagged it, a deputy found a second forged license in {D}'s wallet, and the State will show {D} meant to pass them as real.", "{D} ordered novelty cards from a website that labels them for novelty use only, and the clerk stopped the sale before any beer left the store. The defense says a foolish teenager's attempt, caught at the register, is not the serious fraud the State claims."),
        closings: ("The cards carry {D}'s photo and a false name and birth date, the scanner caught them, and a second card sat in {D}'s wallet. {D} handed one across a counter to buy alcohol, and that is how a forged license is meant to be used.", "No beer was sold, no one was harmed, and {D} stayed at the counter and told the deputy the truth. The fine print said novelty, and this was a teenager's foolish stunt that was stopped at the first scan."),
        timeline: [(-14, "{DL} orders the licenses online."), (0, "{DL} presents one at the gas station."), (0, "A deputy finds the second in {D}'s wallet.")],
        identified: "The clerk's scanner.",
        genders: ["D": .male])

    static let paintCans = SmallCases.make(
        key: "story.paintCans",
        category: .property,
        headlines: ["Man Walked Out With $400 in Paint", "Paint Store Camera Shows Cans in Backpack"],
        law: "larcenyMerchant",
        threshold: 6,
        spec: "Stole $412 in paint from a retail merchant, concealing it in a bag, on {DATE}.",
        ages: 19...55,
        victim: false,
        summary: "A home improvement store camera recorded {D} placing five gallons of paint, each $82, into a large backpack in the paint aisle on {DATE} and walking out past the registers. {D} was stopped in the lot. {DL} says {D.he} was painting for a landlord who had promised to pay and that {D.he} meant to pay.",
        state: [E(.video, 3, "Store Camera", "{D} fills a backpack with five paint cans and walks out the garden exit."), E(.document, 2, "Loss Report", "Five gallons at $82 each, $412 total.")],
        defense: [E(.statement, 1, "Landlord's Job", "{DL}'s landlord says {D.he} was hired to paint the units.")],
        role: "Home improvement store manager",
        exam: [.direct("What does the store camera show?", "\"In the paint aisle, {D} lifts five gallons of paint into a large backpack, one after another, then walks past the registers and out through the garden exit.\""), .direct("What was the value of what was taken?", "\"The paint was five gallons at $82 each, so $412 total. Our loss report lists each can, and {DL} did not pay for any of them.\""), .direct("How did you come to confront {D}?", "\"Our staff watched on camera and I met {D.him} in the parking lot. {D.He} stopped when I called out and was holding the backpack, which was very heavy.\""), .direct("How are the paint cans displayed in that aisle, and how heavy is a gallon?", "\"They sit on open shelves at waist height, and a gallon weighs about ten pounds. Five cans in one backpack is a heavy load that is hard to carry around the store without noticing.\""), .direct("Which way did the defendant walk after loading the backpack?", "\"Straight down the paint aisle, past the end of the registers, and out the garden exit. The video shows {DL} never stopped at a checkout lane.\""), .direct("What did you say to the defendant in the lot?", "\"I identified myself as the store manager and asked {DL} to come back inside. {DL} set the backpack on the ground and told me about a painting job.\""), .cross("{D} didn't run when you approached, did {D.he}?", "\"No. {D.He} stood right there and did not try to get away. I'll say that in fairness.\""), .cross("{D} told you about a painting job for a landlord, didn't {D.he}?", "\"Yes, {DL} said a landlord had hired {D.him} to paint some units and promised to pay. I didn't have a way to check that.\""), .cross("Is it true the garden exit is closer to the paint aisle than the front registers?", "\"It is somewhat closer, yes. But it is not a checkout lane. There is no register at the garden exit, and nothing gets paid for there.\""), .cross("Is the garden exit marked as an exit that customers may use?", "\"It is a regular exit for lawn and garden customers, but the paint is sold at the front registers. Customers are expected to pay inside before leaving.\""), .cross("Did the defendant try to leave the lot after you called out?", "\"No. {D.He} stopped by the truck and stayed there while I walked over, which is why we were able to settle what was in the bag.\"")],
        theory: ("{D} put $412 of paint in a bag and walked out.", "A painter on a job who meant to pay."),
        allocution: "\"I was short on cash. I'll pay it back.\"",
        truths: ("{DL} had sold the paint to a landlord for cash two days earlier.", "The landlord confirmed hiring {DL}, but had paid in advance for the paint."),
        defendant: [.direct("Why did you go to the home improvement store that day?", "\"I had a painting job at a landlord's rental units and needed five gallons of paint to start. I went to get the color the landlord picked.\""), .direct("How was the landlord going to pay for the paint?", "\"The landlord promised to pay me for the job and the supplies. I meant to settle up with the store once I got paid, and I thought that was acceptable.\""), .direct("Why did you put the cans in a backpack?", "\"They were heavy, and I did not have a cart. I figured the backpack was easier to carry. I did not think about how it would look.\""), .direct("Tell the jury what job you were working on.", "\"A landlord had hired me to repaint several rental units over two weeks. I needed five gallons that day to finish the first unit, and I was out of room on my credit card.\""), .direct("What was your plan for paying for the paint?", "\"The landlord had said to buy it and bring a receipt for reimbursement. I planned to explain it at the register and ask to set up an account, but I never got that far.\""), .direct("What did you do when the manager came out to the lot?", "\"I stopped walking and put the backpack on the ground. I told the manager exactly what the paint was for and offered to pay if the store would let me.\""), .cross("You walked past every register without paying, didn't you?", "\"I did. I know that is how it looks. I intended to come back and pay, but I should have paid first, no question.\""), .cross("Why leave through the garden exit instead of a register?", "\"It was closer to my truck and the cans were heavy. I wasn't thinking about the cameras or anything else, honestly.\""), .cross("Did you have any receipt or written agreement with the landlord for the paint?", "\"No, nothing in writing. It was a handshake arrangement, and I know that does not help me with the store.\""), .cross("If you meant to pay, why did you pass every register with a backpack full of paint?", "\"I made a bad decision. I was tired and in a hurry, and I told myself I'd sort it out with the landlord first. I see how that looks.\""), .cross("You didn't ask anyone at the store about an account before loading the bag. Why not?", "\"I didn't think of it until I was already in the aisle. If I had asked first, none of this would have happened.\"")],
        openings: ("A home improvement store camera records {D} loading five gallons of paint into a backpack and walking past every register to the garden exit. The total is $412, and none of it was paid for.", "{D} was a painter on a job, hauling heavy cans to a truck with the plan to settle up when the landlord paid. The defense will show a person who did not run, did not hide, and meant to pay."),
        closings: ("Five gallons, a backpack, the garden exit, and no payment. The video shows a deliberate path out of the store, and a promise to pay later is not permission to walk out with $412 of paint.", "{D} stood still when the manager called out and gave a straight account of a painting job. That is not the conduct of a thief. The State has not proved {D} intended to keep the paint without paying."),
        timeline: [(0, "Midday: the paint goes into the backpack."), (0, "{DL} leaves through the garden exit."), (0, "The manager stops {DL} in the lot.")],
        identified: "The store camera and the manager.",
        genders: ["D": .male])

    static let dumpsterFire = SmallCases.make(
        key: "story.dumpsterFire",
        category: .property,
        headlines: ["Dumpster Fire Behind Restaurant Called Arson Attempt", "Cook Charged After Trash Fire Behind Kitchen"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a commercial dumpster, by fire, causing damage of $900, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "A dumpster behind a restaurant burned on {DATE} at 2 a.m. The fire was out before it reached the building. {V}, the owner, had fired {D} the day before for no-call, no-show. The kitchen's back camera showed a person in a hooded jacket lighting something near the dumpster. {DL} says {D.he} was at a friend's house.",
        state: [E(.video, 3, "Kitchen Camera", "A hooded figure lights a rag and drops it into the dumpster at 1:58 a.m."), E(.document, 2, "Fire Marshal's Report", "Accelerant not found; paper trash ignited by an open flame.")],
        defense: [E(.statement, 1, "Alibi", "A friend says {DL} was at their apartment until 3 a.m.")],
        role: "County fire marshal",
        exam: [.direct("What did you find when you arrived at the restaurant?", "\"Crews were already knocking down a dumpster fire behind the building. It was out by about 2:05 a.m., and the flames never reached the back wall.\""), .direct("What did you determine about how it started?", "\"I found no accelerant. The fire began in paper trash, and the pattern shows it was ignited by an open flame at the front edge of the dumpster.\""), .direct("What does the kitchen's back camera show?", "\"A person in a hooded jacket at 1:58 a.m. lights a rag, drops it into the dumpster, and walks out of frame. The face is never visible.\""), .direct("Who did the owner suspect?", "\"{V} had fired {D} the day before for a no-call, no-show. {V} suggested {DL} right away, though the owner admitted the figure's face wasn't visible.\""), .direct("What was recovered from {D}'s car or belongings?", "\"I'm told a lighter and a burnt rag were found in {DL}'s car, though I'd have to rely on the deputy's report for exactly where.\""), .direct("What was the damage?", "\"The dumpster was a total loss and the back wall had scorch marks. No one was hurt and the kitchen equipment was undamaged.\""), .cross("Isn't it true the person on the video is never identified by face?", "\"Correct. The hood covers most of the face, and the camera is mounted high. I can't identify the person by facial features.\""), .cross("Did you find any accelerant?", "\"No. The lab found nothing like gasoline or lighter fluid. That makes the fire consistent with a flame applied to ordinary paper.\""), .cross("Could a lighter in a car be explained innocently?", "\"Plenty of people carry lighters and old rags in a car. That fact alone doesn't tell me when or how either was used.\""), .cross("Did you check where the defendant was at 1:58 a.m.?", "\"A friend told deputies {DL} was at their apartment until 3 a.m. I haven't confirmed or disproved that, since it isn't my investigation.\""), .cross("Did anyone else have a reason to be upset at the restaurant?", "\"I understand another cook was also let go recently. I didn't interview that person, and I can't tell how closely the build matches the figure.\"")],
        theory: ("{D} set a dumpster on fire after being fired.", "A hooded figure and an alibi."),
        allocution: "\"I was angry about the job. I'll pay for the dumpster.\"",
        truths: ("{DL}'s lighter and a burnt rag were found in {D.his} car.", "The figure's walk and size matched another cook who had also been fired."),
        defendant: [.direct("Where were you at 2 a.m. that night?", "\"I was at a friend's apartment, playing video games, and I stayed until after three. My friend can tell you I never left.\""), .direct("How did you feel about being fired?", "\"I was upset, no question. I'd missed a shift because of a family emergency and I didn't think firing me over it was fair.\""), .direct("Did you start that fire?", "\"No. I would never set a fire behind a building where people work. I liked the people there, and the owner was mostly fair to me.\""), .direct("Why do you have a lighter in your car?", "\"I smoke, and I keep a lighter in the car like a lot of people. The rag is an old shop rag I use to wipe the windshield.\""), .direct("When did you hear about the fire?", "\"The next day from a former coworker. I was shocked and stunned to be told the owner thought it was me.\""), .direct("What did you do when the deputies came?", "\"I answered every question, told them where I'd been, and gave them my friend's name and number. I've got nothing to hide.\""), .cross("You had been fired the day before, correct?", "\"Yes, that's true. I was angry and hurt, and I won't deny it. That doesn't mean I'd do something like this.\""), .cross("You know that kitchen's back door and the dumpster, don't you?", "\"I worked there for months and took trash out every night. That's exactly why it makes no sense for me to be the one caught on its camera.\""), .cross("You own a dark hooded jacket?", "\"I do. Half the people I know do. It was a cool night, and a hoodie in the dark isn't hard to find.\""), .cross("Can your friend vouch for every minute that night?", "\"We were together the whole evening, though I stepped out to get a drink at one point. I can't swear I was never out of sight for ten minutes.\""), .cross("You carry a lighter and a rag in the car where deputies found them?", "\"Yes, they were in my car. I've explained why. I can't prove they weren't used, but I know I did not use them on that dumpster.\"")],
        openings: ("At 1:58 in the morning a hooded figure lit a rag and dropped it in a restaurant dumpster, and the fire was out by 2:05 before it reached the building. The owner had fired {D} the day before, and the State will point to {D}'s motive and what was found in {D}'s car.", "The camera shows a hood and no face, and the fire marshal found no accelerant and no one at the scene. The defense says {D} was at a friend's apartment, and the State is asking the jury to convict on motive and a lighter any smoker would carry."),
        closings: ("A firing the day before, a fire at 1:58 behind the same restaurant, and a lighter and a burnt rag in {D}'s car. The camera hides the face, but the circumstances point to one person with a reason to be angry.", "No face on the video, no accelerant, and an alibi from a friend who was there. The State has a motive and a few common items, and that is not enough to prove {D} lit that dumpster."),
        timeline: [(-1, "{DL} is fired from the restaurant."), (0, "1:58 a.m.: the dumpster is lit."), (0, "2:05 a.m.: the fire is out; the owner calls deputies.")],
        identified: "{V}'s guess and the kitchen camera.")

    static let tipJar = SmallCases.make(
        key: "story.tipJar",
        category: .property,
        headlines: ["Man Took Tip Jar From Coffee Shop Counter", "Barista Chases Thief Out With Tip Jar"],
        law: "misdLarceny",
        spec: "Stole $86 in cash from a tip jar belonging to {V}, a coffee shop, on {DATE}.",
        ages: 18...50,
        victim: true,
        summary: "A man walked into a coffee shop on {DATE} while the barista was in the back, lifted the tip jar from the counter, and ran out. The jar held $86. {V}, the owner, saw it on the camera. {D} was stopped by a deputy a block away holding a handful of bills. {DL} says {D.he} found the jar on the sidewalk.",
        state: [E(.video, 3, "Shop Camera", "A man lifts the jar and runs out at 3:15 p.m."), E(.physical, 2, "Cash", "$61 in small bills in {D}'s pocket; an empty jar in a trash can.", .search)],
        defense: [E(.statement, 1, "Found Jar", "{DL} says {D.he} found the jar on the sidewalk.")],
        role: "Coffee shop owner",
        exam: [.direct("What did you see on your shop camera that afternoon?", "\"At 3:15 p.m., while the barista was in the back, somebody walked in, lifted the tip jar off the counter, and ran out the door.\""), .direct("How much was in the jar?", "\"About $86 in bills and coins, the tips the staff had collected through that day. It was a clear jar, so the money was easy to see.\""), .direct("How did {D} come into the picture?", "\"A deputy stopped {D} a block away shortly after I called. {D.He} had a handful of bills, and our empty jar turned up in a trash can nearby.\""), .direct("Where was the barista when the jar was taken?", "\"In the back room restocking cups. The counter was unattended for about two minutes, which is why I went to the camera as soon as I heard the door slam.\""), .direct("Describe how the jar disappeared on the video.", "\"A person in a dark cap walks to the counter, lifts the jar with both hands, turns around, and runs out the front door. The whole thing takes under ten seconds.\""), .direct("What happened when the deputy came back to the shop?", "\"The deputy brought {DL} to the sidewalk so I could see {DL}. I told the deputy I couldn't be certain of the face, but the clothing looked similar to what I'd seen on the screen.\""), .cross("Isn't it true the jar was found empty in a trash can, not on the defendant?", "\"Yes, the jar was in a trash can. The cash was in {D.his} pocket, $61 of it, which is less than what the jar held.\""), .cross("You didn't see the person's face clearly on the video, did you?", "\"The footage is decent but the person is moving fast and wearing a cap. I can tell you the build and clothes matched what deputies found.\""), .cross("Has your shop ever had customers set a jar down outside?", "\"Occasionally the staff puts a bench out front, and a customer could set something down. I can't say that is what happened with this jar.\""), .cross("How long between the jar being taken and the defendant being stopped?", "\"About two minutes by the deputy's report, which is close. But that also means {DL} had time to be anywhere within a couple of blocks.\""), .cross("Did you recover any of the jar's contents from the defendant?", "\"The deputy found bills in {DL}'s hand, but I cannot say they were the tips from our jar. We never had a count that matched.\"")],
        theory: ("{D} took the tip jar and ran.", "A finder who picked up money from the sidewalk."),
        allocution: "\"I needed the money. I'm sorry for taking it from workers.\"",
        truths: ("The video showed {DL} grinning at the counter before he took the jar.", "The barista later said the jar had been set on the sidewalk bench by a customer."),
        defendant: [.direct("Where did you get the money in your pocket?", "\"Some of it was mine and some of it was from the jar I found. I picked up a jar from the sidewalk and found money in it.\""), .direct("Why did you run?", "\"A deputy and some others were coming at me and I thought someone was chasing me. I got scared and started moving without thinking.\""), .direct("What did you do with the jar after you found it?", "\"I emptied what was in it, pocketed the cash, and tossed the jar in a trash can. I'd say it was a bad decision.\""), .direct("Tell the jury where you were walking that afternoon.", "\"I was walking along the main street to the bus stop. I'd been to the pharmacy and was looking for a place to sit down.\""), .direct("What did you find on the sidewalk?", "\"A glass jar with cash in it, sitting on a bench outside the coffee shop. I looked around, didn't see anyone, and thought it had been left.\""), .direct("What happened when the deputy approached you?", "\"I was walking fast with the money in my hand. The deputy yelled and I started to run because I thought I was in trouble for having it.\""), .cross("The video shows someone taking the jar off the counter. You say that wasn't you?", "\"I do not remember it that way. I remember finding it outside. I'm not saying the video is wrong, but I don't remember being inside.\""), .cross("You had $61 on you. Is that your tip money or the jar's?", "\"Some of it was mine. I cannot tell you exactly how much, and I know that's a weak answer for you.\""), .cross("If you found a jar of money, why not turn it in?", "\"I wish I had. I wasn't thinking straight, and when people started yelling, I only wanted to get away.\""), .cross("If the jar was left on a bench, why take the money out and keep walking?", "\"I wasn't thinking clearly. I picked up the jar, saw the cash, and made a bad decision to take some before looking for the owner.\""), .cross("You ran from a deputy. Isn't that what someone does who knows the money isn't theirs?", "\"I ran because I was scared. I should have stopped right away and explained, and I understand now how it looks.\"")],
        openings: ("At 3:15 on a weekday afternoon, someone lifted a tip jar off a coffee shop counter and ran out. A deputy stopped {D} a block away with a handful of bills and an empty jar in a nearby trash can.", "The defense evidence includes a jar of money sitting outside, a person who picked it up, and a panic when strangers came running. Finding something on the sidewalk is not the same as taking it from a counter."),
        closings: ("The camera shows the jar being taken, the deputy found {D} a block away, and the cash was in {D}'s pocket. An empty jar in the trash tells you everything about where the tips went.", "No one can say the person in the shop and the person on the sidewalk are the same. A found jar and a frightened run do not prove larceny from a counter."),
        timeline: [(0, "3:15 p.m.: the jar is taken."), (0, "3:17 p.m.: a deputy stops {DL} a block away."), (0, "3:30 p.m.: the empty jar is found in a trash can.")],
        identified: "The shop camera and a deputy's quick stop.",
        genders: ["D": .male])

    static let shedBreakIn = SmallCases.make(
        key: "story.shedBreakIn",
        category: .property,
        headlines: ["Backyard Shed Broken Into, Tools Gone", "Neighbor's Mower Blade Found in Man's Garage"],
        law: "feloniousBE",
        spec: "Broke and entered a building, a backyard storage shed belonging to {V}, with intent to commit larceny therein, on {DATE}.",
        ages: 19...55,
        victim: true,
        summary: "{V}'s backyard shed was pried open on {DATE} and a leaf blower, a mower blade, and a set of wrenches taken. A deputy later found a mower blade matching {V}'s in {D}'s garage. {D} lives two houses away. {DL} says {D.he} bought the blade at a yard sale.",
        state: [E(.physical, 3, "Mower Blade", "A mower blade with {V}'s paint mark, in {D}'s garage.", .search), E(.physical, 2, "Pry Marks", "Fresh pry marks on the shed's hasp.")],
        defense: [E(.statement, 1, "Yard Sale", "{DL} says {D.he} bought the blade for $5 at a yard sale.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find at the shed?", "\"The hasp had been pried off with fresh pry marks on the wood. The owner reported a leaf blower, a mower blade, and a set of wrenches missing.\""), .direct("What did you find at {D}'s home?", "\"With {D}'s consent I searched the garage and found a mower blade that carries the owner's paint mark. {D.He} lives two houses down from {V}.\""), .direct("What did the defendant tell you about the blade?", "\"{D.He} said it was a yard sale purchase and described paying about five dollars for it. I wrote down that account at the scene.\""), .direct("What was the condition of the shed when you arrived?", "\"The hasp had been pried off with a flat tool and the door stood open. The inside was disturbed, with a leaf blower, a mower blade, and a set of wrenches missing.\""), .direct("How did you identify the mower blade at the defendant's home?", "\"It carried {V}'s paint mark on the edge, a dab of orange that {V} puts on every blade to tell them apart. I compared it to the mate of the blade still in the shed.\""), .direct("Where is the defendant's home in relation to {V}'s?", "\"Two houses down on the same side of the street. The backyards are separated by a chain link fence and a short walk.\""), .cross("No one saw the defendant at the shed that night, correct?", "\"Correct. I have no eyewitness who placed {D.him} at the shed, and I didn't recover the leaf blower or wrenches from the garage.\""), .cross("Blades like that are sold all over, aren't they?", "\"Many are alike, but this one has {V}'s paint mark, which is what drew my attention. Without it I would not have made the connection.\""), .cross("{D} consented to the search, didn't {D.he}?", "\"Yes. {D.He} agreed to let me look and was cooperative the entire time. I did not need a warrant to go in.\""), .cross("Did you find the leaf blower or the wrenches in the defendant's garage?", "\"No. Only the blade turned up, and nothing else from the shed was recovered at {D.his} home.\""), .cross("Would a pry mark on a hasp tell you which tool was used?", "\"It tells me a flat tool was used, but not whose. I did not find a matching pry bar at {D.his} home either.\"")],
        theory: ("{D} pried open a shed and took tools; the blade is in {D.his} garage.", "A yard sale bargain."),
        allocution: "\"I took the tools. I'll give them back.\"",
        truths: ("A neighbor's camera showed {DL}'s truck backing to the shed at 2 a.m.", "The yard sale seller later confirmed selling {D} the blade."),
        defendant: [.direct("Did you break into {V}'s shed?", "\"No. I did not touch {V}'s shed, and I did not take anything from it. I've never even been in the backyard.\""), .direct("Where did the mower blade come from?", "\"I bought it at a yard sale for about five dollars. I needed a blade for my own mower, and it looked like it would fit.\""), .direct("Did you notice any paint mark on the blade?", "\"I saw some marks, but a lot of blades have paint or scratches. I didn't connect it with anyone and I didn't look any closer.\""), .direct("Walk us through what you were doing on the night the shed was forced.", "\"I was at home asleep. I work early, so I'm usually in bed by ten, and nobody in my house was up at two.\""), .direct("What can you tell us about the yard sale?", "\"It was a few Saturdays before. A table of tools and blades was on a front lawn, and I paid five dollars cash for a mower blade I needed.\""), .direct("What happened when the deputy asked to look in your garage?", "\"I told the deputy to go ahead. I showed the blade and explained where it came from, and I wasn't worried because I knew how I'd gotten it.\""), .cross("You live two houses from {V}. Isn't that quite a coincidence?", "\"It's a small neighborhood, and I understand how it looks. But the blade came from a sale, and I'm telling you honestly I did not take it.\""), .cross("Do you have a receipt for the blade?", "\"No. It was a five-dollar cash deal at a yard sale, so no receipt, and I can't give you the exact address.\""), .cross("You let the deputy search, knowing the blade was there?", "\"I did, because I had nothing to hide. I told the deputy exactly where I got it as soon as it came up.\""), .cross("The blade has {V}'s paint mark on it. How did a blade from {V}'s shed end up at a yard sale?", "\"I don't know. I assume whoever sold it to me got it from somewhere, and I had no way to know it came from a shed two houses away.\""), .cross("You didn't ask the seller's name or where the blade came from?", "\"No. It was five dollars at a yard sale, and I figured the seller was clearing out a garage. I should have asked.\"")],
        openings: ("A backyard shed was pried open, and a leaf blower, mower blade, and wrenches disappeared. A deputy then found a blade bearing the owner's own paint mark in a garage two houses away, belonging to {D}.", "{D} bought a mower blade at a yard sale for five dollars and let a deputy search the garage without a fight. The defense will show that no one saw {D} at that shed."),
        closings: ("Fresh pry marks, a missing blade, and a blade with the owner's paint mark in the garage of a neighbor two houses down. That mark does not belong to a yard sale. It belongs to {V}.", "No witness, no video, and no stolen tools beyond one blade that {D} openly shared. A cheap yard sale blade and a cooperative search are not proof of a break-in."),
        timeline: [(0, "2 a.m.: the shed is forced."), (0, "Morning: {V} finds the pried hasp."), (3, "A deputy finds the blade in {DL}'s garage.")],
        identified: "A deputy's search with {D}'s consent.",
        genders: ["D": .male])

    static let scaleAndBags = SmallCases.make(
        key: "story.scaleAndBags",
        category: .drugs,
        headlines: ["Digital Scale and Baggies Found in Car at Traffic Stop", "Driver Says They Were for Jewelry, Not Drugs"],
        law: "possParaphernalia",
        spec: "Knowingly possessed drug paraphernalia, a digital scale and plastic bags, with intent to package a controlled substance, on {DATE}.",
        ages: 19...45,
        victim: false,
        summary: "A deputy stopped {D} for running a stop sign on {DATE} and found a digital scale and a roll of small plastic bags in the console. A drug dog alerted but no drugs were found. {DL} says {D.he} sells handmade jewelry at craft fairs and uses the scale for beads.",
        state: [E(.physical, 3, "Scale and Bags", "A digital scale with white residue and a roll of 2-inch zip bags.", .search), E(.document, 2, "Dog Alert", "The dog alerted on the console.")],
        defense: [E(.document, 2, "Craft Fair Receipts", "{DL}'s receipts for jewelry sales at three fairs.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop {D}'s vehicle?", "\"I saw {D} run a stop sign and initiated a traffic stop. While talking to {D.him}, I saw part of a digital scale in the center console.\""), .direct("What did you find in the console?", "\"A digital scale with a white residue on the platform and a roll of small two-inch zip bags. I seized both and sent the residue for testing.\""), .direct("What did your drug dog do?", "\"The dog alerted on the console area during the walk-around. I did not find any actual drugs in the car or on {DL}.\""), .direct("What did you smell or see when you first approached the vehicle?", "\"Nothing out of the ordinary at the window. {D.He} was calm and handed over a license and registration, and I asked to run the dog because of the scale I saw in the console.\""), .direct("How did you find the scale and bags?", "\"They were in the center console, with the scale in the open and a roll of small bags beside it. I photographed them where they sat.\""), .direct("What does a dog alert mean, and what does it not mean?", "\"It means the dog reacted to an odor it was trained on, either at that moment or some time before. It does not mean drugs are present in the vehicle.\""), .cross("No controlled substances were found at all, were there?", "\"That's correct. The dog alerted, but I did not locate any drugs, and I did not make a drug arrest.\""), .cross("{D} showed you receipts for craft fair sales, didn't {D.he}?", "\"Yes, {D.he} produced receipts for jewelry sales at three craft fairs. I looked at them and noted them in my report.\""), .cross("Small zip bags and a scale are common items for crafts, aren't they?", "\"They are used for crafts, yes. They are also used for drugs. That is why I considered the residue and the dog alert together.\""), .cross("Did you test the residue on the scale in the field?", "\"I did a field test and it was inconclusive. The sample went to the lab afterward.\""), .cross("Did you find anything else in the car, like cash, notes, or other packaging?", "\"No. There was a bag of beads, some jewelry wire, and a cardboard display, which is consistent with what {D.he} told me.\"")],
        theory: ("{D} had a scale and bags with residue for packaging drugs.", "A jewelry maker with a bead scale."),
        allocution: "\"I used to sell. I'm trying to change.\"",
        truths: ("{DL}'s phone held texts about selling grams the month before.", "The residue was bead powder, the lab found."),
        defendant: [.direct("What do you use the scale for?", "\"I make handmade jewelry and sell it at craft fairs. I weigh beads and small materials, and the scale helps me price things consistently.\""), .direct("What about the small bags?", "\"I use them to package earrings and small pieces for sale. Craft fair customers like to carry things home in a little bag.\""), .direct("What was the residue on the scale?", "\"It was powdered clay and bead dust from my work. I handle polymer clay all the time, and it leaves a fine powder on everything.\""), .direct("Tell the jury how you got into making jewelry.", "\"I started making earrings as a hobby and began selling them at craft fairs about two years ago. I do three or four fairs a season.\""), .direct("What are the small bags for, and how do you use the scale?", "\"The bags hold earrings and sets for display. The scale weighs beads and findings so I can price a set by weight.\""), .direct("What happened when the deputy ran the dog around your car?", "\"I stood on the side of the road and waited. I told the deputy it was a bead scale and offered to show the receipts from the fairs.\""), .cross("A drug dog alerted on your console. Can you explain that?", "\"I can't explain it. I do not use drugs and I did not have any, and I don't know why the dog alerted there.\""), .cross("Many people with scales and baggies are selling drugs, aren't they?", "\"Maybe, but I'm not one of them. I have my receipts from three craft fairs that show what I sell.\""), .cross("Have you ever bought or sold anything other than jewelry?", "\"No. I have never sold drugs, and everything I make and sell is jewelry. The receipts will show you that.\""), .cross("A dog alerted on the console. What was in there that could cause that?", "\"I can't say. Other people have ridden in that car, and I can't know what they might have left or carried.\""), .cross("Do you sell anything at craft fairs besides jewelry?", "\"No. I sell earrings, bracelets, and a few necklaces, and the receipts I gave the deputy show the sales.\"")],
        openings: ("A routine stop sign violation led a deputy to a digital scale with white residue and a roll of small zip bags in {D}'s console. A drug dog alerted on that spot, and the State will explain why that matters.", "{D} makes jewelry and sells it at craft fairs. The defense will show receipts, a scale used for beads, powdered clay as the residue, and no drugs anywhere in the car."),
        closings: ("A scale with residue, a roll of small bags, and a dog that alerted. Put those together and they tell a story about packaging. Craft supplies do not usually come with residue and an alert.", "No drugs were found, not one. Receipts show a working jewelry maker, and the residue is bead dust. A scale and some zip bags are not a crime in themselves."),
        timeline: [(0, "Evening: the stop for a stop sign."), (0, "The dog alerts on the console."), (0, "The scale and bags are seized.")],
        identified: "A traffic stop and a dog sniff.",
        doctrines: ["searchSeizure", "burdenOfProof"])

    static let airsoftCar = SmallCases.make(
        key: "story.airsoftCar",
        category: .violent,
        headlines: ["Teens Say Man Pointed Pistol at Them From Car", "Airsoft Pistol Pointed at Teens Looked Real"],
        law: "assaultPointingGun",
        spec: "Assaulted {V} by pointing a gun, an airsoft pistol that appeared to be a handgun, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "Three teenagers walking home on {DATE} told deputies a driver pulled alongside them and pointed a black pistol out the window, yelling, \"Get off my road.\" {V} said it looked real and ran into a yard. Deputies stopped {D} a mile away and found an airsoft pistol on the seat. {DL} says it was a toy and the boys had thrown a bottle at the car.",
        state: [E(.physical, 3, "The Pistol", "An airsoft pistol, black, with the orange tip removed, on the passenger seat.", .search), E(.statement, 2, "Teens", "All three say the gun looked real and they feared being shot.")],
        defense: [E(.statement, 1, "Bottle", "{DL} says one of the boys threw a bottle at {D.his} car.")],
        role: "Sheriff's deputy",
        exam: [.direct("What was reported to you that evening?", "\"Three teenagers walking home at dusk told me a driver pulled alongside them, pointed a black pistol out the window, and yelled, Get off my road.\""), .direct("How did the teenagers appear when you spoke to them?", "\"Frightened. One had run into a yard and the others were shaking. Each separately said the gun looked real to them and that they feared being shot.\""), .direct("What vehicle did they describe?", "\"They gave the make and color and the direction it went. About a mile away I stopped a matching car, and {D} was driving it.\""), .direct("What did you find in the car?", "\"On the passenger seat was a black airsoft pistol. The orange safety tip that usually marks these guns had been removed, so it looked like a firearm.\""), .direct("How did {D} explain the pistol?", "\"{DL} said it was a toy and that the boys had thrown a bottle at the car. {DL} admitted showing it out the window to scare them.\""), .direct("Did you check for any bottle?", "\"A deputy found a bottle in the street near where {DL} said it happened. I can't say who threw it or when it got there.\""), .cross("Isn't it true the pistol was an airsoft toy?", "\"Yes. It's an airsoft pistol, a spring-powered toy that shoots plastic pellets. But to a teenager in the dusk, without the orange tip, it looks like the real thing.\""), .cross("Did the defendant ever fire it?", "\"No one reported a shot or a pellet, and the teenagers didn't say it was fired. I didn't find any new marks on them or nearby.\""), .cross("Did the defendant say anything to the teenagers beyond the words quoted?", "\"Only what the teens reported, the words get off my road. {D.He} didn't mention more to me, and the teens didn't describe a longer threat.\""), .cross("Were the teenagers on the roadway?", "\"They were walking along the edge. I wouldn't say they were in the lane, but it's a narrow road with no sidewalk.\""), .cross("Did you see anyone throw a bottle at the defendant's car?", "\"No. I only know what {D.he} said and that a bottle was found in the street. The teenagers didn't mention a bottle in their statements.\"")],
        theory: ("{D} pointed a realistic pistol at three teenagers.", "A toy pistol shown to boys who threw a bottle."),
        allocution: "\"I was angry. I wanted to scare them. I'm sorry.\"",
        truths: ("{DL} had removed the orange tip the week before so it would look real.", "A bottle was found in the street near {DL}'s car."),
        defendant: [.direct("What happened on the road that evening?", "\"A bottle hit my car as I drove past three boys walking. It startled me and I pulled alongside and held the toy up to scare them.\""), .direct("What was the pistol?", "\"An airsoft pistol I'd had for a long time. I'd keep it in the car from a day at the field and never meant to use it on anyone.\""), .direct("Did you point it at them?", "\"I showed it out the window, yes. I wanted them to stop throwing things, and I wasn't thinking about how it would look in the dusk.\""), .direct("What did you say?", "\"I said, get off my road. I was angry and shouted it, and I'm sorry for how it must have sounded.\""), .direct("What did you do after that?", "\"I drove away, and I was about a mile down when the deputy stopped me. I told the truth about the toy and showed where it was.\""), .direct("How would you describe your state of mind?", "\"Scared and angry. A bottle can break a windshield or put someone off the road, and I reacted badly without thinking.\""), .cross("You took the orange tip off that pistol, didn't you?", "\"I did, a week before. I'd wanted it to look more real for games, and I didn't think about what that meant on a public road.\""), .cross("So it looked like a real pistol to anyone seeing it?", "\"Yes. I know that now. Without the tip it looks the same as a real one from a few feet away.\""), .cross("You pulled alongside people walking on foot?", "\"I did. They were close to the road edge and I drew up next to them. I know now that I should have just kept driving.\""), .cross("Did you see which of them threw the bottle?", "\"No. I only saw the bottle hit the car. I assumed it was them since nobody else was around, and I could be wrong.\""), .cross("You yelled at three teenagers while holding a gun-shaped object?", "\"I did, and I can see why they ran. I hoped to frighten them, and it worked more than I meant it to.\"")],
        openings: ("At dusk, three teenagers walking home saw a driver pull alongside them, point a black pistol out the window, and shout, Get off my road. Deputies found that pistol on {D}'s passenger seat with its orange safety tip removed, and the teens say they thought they were about to be shot.", "The gun was an airsoft toy, shown after a bottle struck {D}'s car. The defense says {D} reacted in anger, never fired anything, and that the State cannot prove a real threat of serious harm."),
        closings: ("The orange tip was gone, the pistol looked real in the dusk, and three teenagers ran for their safety. A driver who points a realistic gun at walkers and tells them to get off the road has put them in fear, whether it fires or not.", "It was a toy, nothing was fired, and a bottle hit the car right before this happened. {D} acted foolishly, but the State must prove a genuine, reasonable threat, and a toy shown in a flash of anger does not do that."),
        timeline: [(0, "Dusk: the bottle thrown at the car."), (0, "{DL} points the pistol out the window."), (0, "Deputies stop {DL} a mile away.")],
        identified: "The teens' description and a deputy's stop.",
        genders: ["D": .male])

}
